var LIB=[{"g":"Email, documents and files","items":[{"id":"microsoft-365","name":"Microsoft 365","job":"Email, documents and files","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation (EU/UK contracts via Microsoft Ireland Operations Limited)","par":null,"parc":null,"store":"UK data centres for tenants signed up in the UK; EU data centres for tenants signed up in the EU. Covers Exchange mail, SharePoint, OneDrive, Teams chat and Copilot.","res":"yes-default","plans":"All commercial plans, including Business Basic and Business Standard, based on the country chosen at sign-up","mfa":"all plans","ai":"no","aid":"Microsoft states prompts, responses and data accessed through Microsoft Graph are not used to train foundation LLMs, including those used by Copilot. This applies to Copilot Chat included with business plans and paid Microsoft 365 Copilot.","np":"Microsoft 365 Business Basic grant for up to 300 users free, plus up to 75% off Business Standard and Business Premium. The free Business Premium grant ended from 1 July 2025.","note":"Your data stays in the UK or EU only if the tenant was set up with a UK or EU country, so check the data location in the admin centre. If you had the free Business Premium grant, check you moved users before it expired, or you risk losing data.","conf":"high","src":[["Overview of Product Terms Data Residency","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-product-terms-dr?view=o365-worldwide"],["Data Residency for Exchange Online","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-exo?view=o365-worldwide"],["Microsoft 365 data locations","https://learn.microsoft.com/en-us/microsoft-365/enterprise/o365-data-locations?view=o365-worldwide"],["Security defaults in Microsoft Entra ID","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"],["Data, Privacy, and Security for Microsoft 365 Copilot","https://learn.microsoft.com/en-us/copilot/microsoft-365/microsoft-365-copilot-privacy"],["Export search results (Microsoft Purview eDiscovery)","https://learn.microsoft.com/en-us/purview/edisc-search-export"],["Microsoft for Nonprofits updates","https://learn.microsoft.com/en-us/industry/nonprofit/microsoft-for-nonprofits/updates"]]},{"id":"google-workspace","name":"Google Workspace","job":"Email, documents and files","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC (EMEA customers usually contract with Google Cloud EMEA Limited, Ireland)","par":"Alphabet Inc.","parc":"US","store":"No location commitment by default. Business Standard and above can set a data region policy to Europe (EU); Business Starter and the free Nonprofits edition cannot. There is no UK-only region.","res":"yes-some-plans","plans":"Business Standard, Business Plus, Enterprise Standard and Plus (EU region via admin setting). Not Business Starter or the free Google Workspace for Nonprofits edition.","mfa":"all plans","ai":"no","aid":"Google states Workspace does not use customer data to train models without the customer's prior permission or instruction. The Privacy Hub refers to qualifying editions and does not list Business Starter or Nonprofits separately.","np":"Google Workspace for Nonprofits edition free; Business Standard about USD 3.50 per user per month and Business Plus about USD 6.16 (annual), through Google for Nonprofits.","note":"On the free Nonprofits edition or Business Starter you cannot choose where your data is stored. To keep data in Europe you need Business Standard or higher and must set the data region to Europe yourself.","conf":"high","src":[["Compare data region features across Google Workspace editions","https://knowledge.workspace.google.com/admin/compliance/compare-data-region-features-across-google-workspace-editions"],["Choose a geographic location for your data","https://knowledge.workspace.google.com/admin/compliance/choose-a-geographic-location-for-your-data"],["Google Workspace Offers for Nonprofits","https://www.google.com/nonprofits/workspace/compare/"],["Generative AI in Google Workspace Privacy Hub","https://knowledge.workspace.google.com/admin/generative-ai/generative-ai-in-google-workspace-privacy-hub"],["Export all your organization's data","https://knowledge.workspace.google.com/admin/migrate/export-all-your-organizations-data"],["Protect your business with 2-Step Verification","https://knowledge.workspace.google.com/admin/security/protect-your-business-with-2-step-verification"]]},{"id":"dropbox","name":"Dropbox","job":"Shared files","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Dropbox, Inc. (outside North America: Dropbox International Unlimited Company, Ireland)","par":null,"parc":null,"store":"US data centres by default. Teams can ask to move data to the UK or EU if they meet conditions.","res":"yes-on-request","plans":"Standard, Advanced, Business, Business Plus or Enterprise teams with at least 10 licences on annual billing; requests reviewed individually","mfa":"all plans","ai":"no","aid":"Dropbox says it will not build generative AI models using customer content without consent. Dash uses OpenAI for web search, on by default in chats, and says data sent is not used to train OpenAI models.","np":"40% off Business Standard and Advanced through TechSoup (announced 2020, for US 501(c)(3) organisations). Availability for UK charities: unknown.","note":"Your files are stored in the US unless your team has at least 10 licences on annual billing and asks Dropbox to move them. Small teams should assume US storage.","conf":"high","src":[["Where is my Dropbox data stored?","https://help.dropbox.com/security/physical-location-data-storage"],["EU Data Act Information","https://help.dropbox.com/security/eu-data-act-information"],["Dropbox AI Principles","https://www.dropbox.com/ai-principles"],["How to search and explore your content with Dropbox Dash","https://help.dropbox.com/view-edit/dropbox-ai-how-to"],["Dropbox plans comparison","https://www.dropbox.com/business/plans-comparison"],["How to require multi-factor authentication for Dropbox teams","https://help.dropbox.com/security/two-step-verification"],["Introducing Dropbox for Nonprofits","https://blog.techsoup.org/en-us/posts/introducing-dropbox-for-nonprofits"]]},{"id":"ionos-nextcloud-workspace","name":"IONOS Nextcloud Workspace","job":"Email, documents and files","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE"],"hq":"DE","co":"IONOS SE (UK customers contract with IONOS Cloud UK Limited)","par":"United Internet AG","parc":"DE","store":"IONOS data centres in Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"The AI assistant runs on the IONOS AI Model Hub. IONOS says it contractually guarantees company data will never be used to train public AI models.","np":null,"note":"Your data is held in Germany and the software is open source, so you can move to another Nextcloud host. The UK contract is with IONOS Cloud UK Limited, so check which entity is on your agreement.","conf":"medium","src":[["Nextcloud Workspace (IONOS UK)","https://www.ionos.co.uk/office-solutions/nextcloud-workspace"],["Nextcloud Workspace - Overview (IONOS docs)","https://docs.ionos.com/cloud/sovereign-workplace/nextcloud-workspace"],["Nextcloud Workspace for Business","https://cloud.ionos.co.uk/sovereign-workplace/nextcloud"],["A sovereign Microsoft 365 alternative: Nextcloud and IONOS join forces","https://nextcloud.com/blog/nextcloud-workspace-microsoft-365-alternative-by-nextcloud-and-ionos/"]]},{"id":"hetzner-storage-share","name":"Hetzner Storage Share","job":"Shared files","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE"],"hq":"DE","co":"Hetzner Online GmbH","par":null,"parc":null,"store":"Hetzner's own data centre in Falkenstein, Germany. No other location offered.","res":"yes-default","plans":"All plans (NX11, NX21, NX31)","mfa":"unclear","ai":"not-applicable","aid":"Hetzner's Storage Share pages advertise no AI features. Any AI apps would be ones you install yourself from the Nextcloud app store.","np":null,"note":"Files are stored in Germany and are not encrypted by default. Hetzner's docs do not mention two-factor login, so check you can switch it on for every user.","conf":"medium","src":[["Storage Share product page","https://www.hetzner.com/storage/storage-share/"],["Which storage is right for me? (Hetzner Docs)","https://docs.hetzner.com/storage/general/which-storage-is-right-for-me/"],["Security - Storage Share FAQ","https://docs.hetzner.com/storage/storage-share/faq/security/"]]},{"id":"mailbox-org","name":"mailbox.org","job":"Email and calendar","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"Heinlein Hosting GmbH (mailbox)","par":"Heinlein Group","parc":"DE","store":"Own servers in data centres in Berlin, Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"not-applicable","aid":"No AI features are listed on mailbox.org's plans or product pages.","np":null,"note":"Mail, calendars and files are stored in Berlin and use open standards, so moving out is straightforward. The service rebranded from mailbox.org to mailbox in September 2025, so look for either name on invoices.","conf":"medium","src":[["Why mailbox","https://mailbox.org/en/why-mailbox/"],["Email hosting for businesses","https://mailbox.org/en/business/"],["Secure email service","https://mailbox.org/en/product/mail/"],["Setting up two-factor authentication in mailbox","https://kb.mailbox.org/en/private/security-and-privacy/how-to-use-two-factor-authentication-2fa/"],["Our price plans","https://mailbox.org/en/prices/"],["Mailbox (company) - Wikipedia","https://en.wikipedia.org/wiki/Mailbox_(company)"]]},{"id":"proton","name":"Proton","job":"Encrypted email and files","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Partial","o":false,"loc":"CH","locs":["CH"],"hq":"CH","co":"Proton AG","par":"Proton Foundation","parc":"CH","store":"Switzerland primarily. Proton says business data is on servers in Europe under Swiss law. Some infrastructure has been moved to Germany and Norway since 2024 to 2025, but no customer choice of location is stated.","res":"unclear","plans":null,"mfa":"all plans","ai":"no","aid":"Proton says Proton Scribe does not use content data to train its models, and Lumo keeps no server-side logs and uses zero-access encryption. Scribe is an add-on; Lumo is included in Workspace Premium.","np":"Discount for registered nonprofits on business plans, amount agreed with sales on request.","note":"Data is mainly held in Switzerland, which is outside the UK and EU but has UK and EU adequacy decisions. Most content is end-to-end encrypted, so if you lose your password and recovery details, the data cannot be recovered.","conf":"medium","src":[["Proton for Business FAQ","https://proton.me/business/faq"],["Proton Privacy Policy","https://proton.me/legal/privacy"],["Proton AG - Wikipedia","https://en.wikipedia.org/wiki/Proton_AG"],["Proton to Expand Infrastructure Beyond Switzerland Over Surveillance Law","https://cyberinsider.com/proton-confirms-gradual-exit-from-switzerland-over-surveillance-law-fears/"],["Proton Mail Export Tool","https://proton.me/support/proton-mail-export-tool"],["Two-factor authentication (2FA)","https://proton.me/support/two-factor-authentication-2fa"],["Nonprofit discount","https://proton.me/business/nonprofit-discount"],["Business suite plans and pricing","https://proton.me/business/plans"]]},{"id":"infomaniak-ksuite","name":"Infomaniak kSuite","job":"Email, documents and files","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Yes","o":false,"loc":"CH","locs":["CH"],"hq":"CH","co":"Infomaniak Network SA","par":null,"parc":null,"store":"Infomaniak's own data centres in Switzerland","res":"no","plans":"Unknown.","mfa":"unclear","ai":"no","aid":"Infomaniak says data sent to its Euria assistant is neither saved nor used to train AI, and processing stays in its Swiss data centres. Euria runs on open source models.","np":"Unknown.","note":"Your data is held in Switzerland, which is outside the UK and EU but has UK and EU adequacy decisions. You can take your data out in standard formats: files over WebDAV, mail over IMAP, contacts as vCard and calendars as ICS. Two-step login is an Infomaniak account setting, so check it is switched on for every staff account. Nonprofit pricing: unknown, so ask Infomaniak.","conf":"medium","src":[["kSuite","https://www.infomaniak.com/en/ksuite"],["kSuite prices","https://www.infomaniak.com/en/ksuite/ksuite-pro/prices"],["Euria: the free, sovereign AI assistant","https://news.infomaniak.com/en/euria-sovereign-ai-assistant/"],["Euria, the sovereign AI assistant","https://www.infomaniak.com/en/euria"],["Nonprofits: Why and How to Migrate to Infomaniak","https://infoswitch.fr/en/blog/nonprofits-migrate-infomaniak"],["Connect to kDrive via WebDAV","https://www.infomaniak.com/en/support/faq/2409/connect-to-kdrive-via-webdav"],["Export all emails from an Infomaniak email address","https://www.infomaniak.com/en/support/faq/1167/export-all-emails-from-an-email-address"],["Export contacts from Infomaniak Contacts","https://www.infomaniak.com/en/support/faq/2593/export-contacts-from-infomaniak-contacts"],["Export a calendar from Infomaniak Calendar","https://www.infomaniak.com/en/support/faq/1173/export-a-calendar-from-infomaniak-calendar"],["Enable Two-Factor Authentication (2FA)","https://www.infomaniak.com/en/support/faq/1940/enable-two-factor-authentication-2fa"]]},{"id":"tuta","name":"Tuta","job":"Encrypted email and calendar","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"Tutao GmbH","par":null,"parc":null,"store":"Tuta's own servers in ISO 27001 certified data centres in Germany","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"not-applicable","aid":"No AI features are listed on Tuta's business or security pages.","np":"50% off for registered nonprofits and schools, by emailing sales with proof of status.","note":"Data is stored in Germany and is end-to-end encrypted. You cannot connect ordinary email apps over IMAP, so exporting mail means using Tuta's desktop app.","conf":"medium","src":[["Security at Tuta","https://tuta.com/security"],["Secure Business Emails","https://tuta.com/business"],["Good causes deserve support","https://tuta.com/discount"],["End-to-End Encrypted Cloud Storage","https://tuta.com/drive"],["We've just added single-click email export to the free Tuta desktop email clients","https://discuss.privacyguides.net/t/we-ve-just-added-single-click-email-export-to-the-free-tuta-desktop-email-clients/24749"]]}]},{"g":"Talking and meeting","items":[{"id":"zoom","name":"Zoom","job":"Video meetings","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Zoom Communications, Inc.","par":null,"parc":null,"store":"Plan assumed: Zoom Workplace Pro. Recordings, transcripts and other customer content are stored in the US by default. Admins on paid plans, including Pro, can move recordings, transcripts, in-meeting chat and whiteboards to Germany, but account and operational data stay in the US.","res":"yes-some-plans","plans":"Paid plans including Pro can set the storage region to Germany for recordings, transcripts, in-meeting chat and whiteboard content. Zoom's fuller EU infrastructure is described for EU Education and Enterprise customers. No UK storage region is listed.","mfa":"all plans","ai":"no","aid":"Zoom's terms (section 10.2) say it does not use audio, video, chat, screen sharing, attachments or other communications-like content to train Zoom or third-party AI models. This applies to all plans; no opt-out is needed.","np":"50% off Zoom Workplace Pro and Business, the Large Meeting add-on and Zoom Webinar for verified nonprofits with budgets under US$10 million, verified through Goodstack. No longer offered through TechSoup.","note":"Recordings are stored in the US unless an admin changes the data storage location to Germany in account settings. Account data stays in the US either way.","conf":"high","src":[["Managing Data & Storage location","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0066473"],["European Union's General Data Protection Regulation (GDPR) | Zoom Trust Center","https://www.zoom.com/en/trust/gdpr/"],["Zoom EU Infrastructure Fact Sheet","https://media.zoom.com/download/assets/zoom-eu-infrastructure-fact-sheet.pdf/3d23251255a811f0bc811651fbd1a193?page=6&onlycontent=1&lang=null"],["Zoom Terms of Service","https://www.zoom.com/en/trust/terms/"],["Cloud recording - Zoom Developer Docs","https://developers.zoom.us/docs/build/cloud-recording/"],["Zoom adds two-factor authentication (2FA) support to all accounts - BleepingComputer","https://www.bleepingcomputer.com/news/security/zoom-adds-two-factor-authentication-2fa-support-to-all-accounts/"],["Secure Your Zoom Account with Two-Factor Authentication","https://www.zoom.com/en/blog/secure-your-zoom-account-with-two-factor-authentication/"],["Subscribing to Zoom as a nonprofit organization","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0080298"],["How do I access Zoom for Nonprofits? (TechSoup)","https://support.techsoup.org/hc/en-us/articles/36503175618203-How-do-I-access-Zoom-for-Nonprofits-I-am-not-seeing-it-on-TechSoup"]]},{"id":"microsoft-teams","name":"Microsoft Teams","job":"Chat and video meetings","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation","par":null,"parc":null,"store":"Plan assumed: Microsoft 365 Business Basic (nonprofit grant) or Business Standard. For a tenant whose default geography is the UK, Teams chats are stored at rest in the UK under Microsoft's Product Terms. EU tenants get EU storage. Meeting recordings are saved to the recorder's OneDrive, which follows the same data residency rules.","res":"yes-default","plans":"All commercial Microsoft 365 plans that include Teams, based on the tenant's default geography (UK or EU). Advanced Data Residency is a paid add-on for stronger commitments.","mfa":"all plans","ai":"no","aid":"Microsoft states that prompts, responses and data accessed through Microsoft Graph are not used to train foundation large language models, including those used by Copilot. Optional feedback may be used to improve the service.","np":"Microsoft 365 Business Basic grant for up to 300 users, and up to 75% off Business Standard and Business Premium. The free Business Premium and Office 365 E1 grants ended for new grants on 1 July 2025.","note":"For UK tenants, Teams chats are stored in the UK. Recordings are saved in the OneDrive of the person who pressed record, so check where they end up when that person leaves.","conf":"high","src":[["Data Residency for Microsoft Teams","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-teams?view=o365-worldwide"],["Overview of Product Terms Data Residency","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-product-terms-dr?view=o365-worldwide"],["Export content with the Microsoft Teams Export APIs","https://learn.microsoft.com/en-us/microsoftteams/export-teams-content"],["Finding content in Microsoft Teams in eDiscovery","https://learn.microsoft.com/en-us/purview/edisc-search-teams"],["Security defaults in Microsoft Entra ID","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"],["Data, Privacy, and Security for Microsoft 365 Copilot","https://learn.microsoft.com/en-us/copilot/microsoft-365/microsoft-365-copilot-privacy"],["Microsoft for Nonprofits updates","https://learn.microsoft.com/en-us/industry/nonprofit/microsoft-for-nonprofits/updates"]]},{"id":"slack","name":"Slack","job":"Team chat","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Slack Technologies, LLC","par":"Salesforce, Inc.","parc":"US","store":"Plan assumed: Pro (free for nonprofits with up to 250 members). Data is stored in the US. Business+ and Enterprise plans can choose data residency in London, Frankfurt, Paris, Stockholm or Zurich, but member profiles, membership details and analytics stay outside the chosen region.","res":"yes-some-plans","plans":"Business+ and Enterprise (London, Frankfurt, Paris, Stockholm, Zurich). Not available on Free or Pro.","mfa":"all plans","ai":"yes","aid":"Slack analyses customer data (messages, content, files) to train non-generative global models, such as emoji and channel recommendations, on all plans by default. Workspace owners can opt out by emailing feedback@slack.com with the subject 'Slack Global model opt-out request'. Slack says it does not train generative AI models on customer data without opt-in consent.","np":"Free Pro plan for workspaces with 250 or fewer members, 85% off Pro above that, and 85% off Business+. Eligibility checked through TechSoup.","note":"On Pro, messages are stored in the US and private channels and DMs cannot be exported. Slack uses your data for its recommendation models unless an owner emails feedback@slack.com to opt out.","conf":"high","src":[["Data residency for Slack","https://slack.com/help/articles/360035633934-Data-residency-for-Slack"],["Export your workspace data","https://slack.com/help/articles/201658943-Export-your-workspace-data"],["Set up two-factor authentication","https://slack.com/help/articles/204509068-Set-up-two-factor-authentication"],["Privacy principles: search, learning and artificial intelligence","https://slack.com/trust/data-management/privacy-principles"],["Apply for the Slack for Nonprofits discount","https://slack.com/help/articles/204368833-Apply-for-the-Slack-for-Nonprofits-discount"],["Slack Main Services Agreement","https://slack.com/main-services-agreement"]]},{"id":"whatsapp","name":"WhatsApp (work groups)","job":"Group messaging","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"WhatsApp LLC (UK users); WhatsApp Ireland Limited (EEA users)","par":"Meta Platforms, Inc.","parc":"US","store":"Plan assumed: free personal WhatsApp accounts used for work groups. Messages are end-to-end encrypted and stored on each member's phone. WhatsApp keeps undelivered messages and media encrypted on its servers for up to 30 days. Other account data is shared globally within Meta, including the US. No UK or EU storage option exists.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Ordinary messages are end-to-end encrypted and are not used to train Meta AI. Anything sent to Meta AI, including when someone types @Meta AI in a group, is not end-to-end encrypted and can be used under Meta's privacy policy. Advanced Chat Privacy, off by default, disables some Meta AI features in a chat.","np":null,"note":"Work messages live on staff and volunteers' own phones, so the charity has no central copy and cannot control what leaves with them. Anyone typing @Meta AI in a group sends that part of the chat to Meta unencrypted.","conf":"medium","src":[["WhatsApp Privacy Policy - UK","https://www.whatsapp.com/legal/privacy-policy-uk"],["WhatsApp Privacy Policy - EEA","https://www.whatsapp.com/legal/privacy-policy-eea"],["What WhatsApp's Advanced Chat Privacy Really Does - EFF","https://www.eff.org/deeplinks/2025/09/what-whatsapps-advanced-chat-privacy-really-does"],["About registration and two-step verification - WhatsApp Help Center","https://faq.whatsapp.com/506595211487528"]]},{"id":"whatsapp-business","name":"WhatsApp Business app","job":"Messaging with supporters","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"WhatsApp LLC (UK users); WhatsApp Ireland Limited (EEA users)","par":"Meta Platforms, Inc.","parc":"US","store":"Plan assumed: the free WhatsApp Business app (not the paid Business Platform API). Chats are stored on the phone the business number is registered on. Other data is shared globally within Meta, including the US. No UK or EU storage option exists.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Messages are end-to-end encrypted and not used to train Meta AI. Any AI tools the business connects are governed by their own terms. Messages sent to Meta AI are not end-to-end encrypted.","np":null,"note":"The app is tied to one phone number and one phone, so decide who holds that phone and how chats are kept when staff change. UK accounts are provided by WhatsApp LLC in the US.","conf":"medium","src":[["WhatsApp Business App Privacy Policy","https://www.whatsapp.com/legal/business-app-privacy-policy"],["WhatsApp Privacy Policy - UK","https://www.whatsapp.com/legal/privacy-policy-uk"],["WhatsApp Privacy Policy - EEA","https://www.whatsapp.com/legal/privacy-policy-eea"],["What WhatsApp's Advanced Chat Privacy Really Does - EFF","https://www.eff.org/deeplinks/2025/09/what-whatsapps-advanced-chat-privacy-really-does"],["About registration and two-step verification - WhatsApp Help Center","https://faq.whatsapp.com/506595211487528"]]},{"id":"signal","name":"Signal","job":"Secure messaging","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"No","o":true,"loc":"US","locs":["US"],"hq":"US","co":"Signal Messenger LLC","par":"Signal Technology Foundation","parc":"US","store":"Plan assumed: the free Signal app. Messages are end-to-end encrypted and stored on members' devices. Signal's servers only queue encrypted messages for offline devices. Its terms say encrypted information and metadata are transferred to the US and other countries. Signal says it can only provide a user's registration date and last connection date.","res":"no","plans":null,"mfa":"all plans","ai":"not-applicable","aid":"Signal cannot read message content, which is end-to-end encrypted, and offers no AI features that use it.","np":null,"note":"Signal holds almost no data about you, but the charity has no admin controls or central copy of chats. Switch on Registration Lock with a PIN to stop someone taking over an account.","conf":"medium","src":[["Signal Terms of Service & Privacy Policy","https://signal.org/legal/"],["Signal Government Communication","https://signal.org/bigbrother/"],["Introducing Signal Secure Backups","https://signal.org/blog/introducing-secure-backups/"],["Signal PIN - Signal Support","https://support.signal.org/hc/en-us/articles/360007059792-Signal-PIN"],["Signal on GitHub","https://github.com/signalapp"]]},{"id":"element","name":"Element (hosted)","job":"Secure team chat","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"GB","co":"Element Creations Ltd (trading as Element)","par":null,"parc":null,"store":"Plan assumed: an Element-hosted server (Element Matrix Services / Element Cloud). Element hosts on Amazon Web Services, with its admin server in Amsterdam and deployment server in Stockholm. Customers choose the location of their own server when they set it up; the list of locations is not published.","res":"unclear","plans":"Location is chosen at set-up for hosted servers. Element's current public pricing page lists only self-hosted plans (Community free for up to 100 users; Enterprise from 100 users), so the small-organisation hosted offer is unclear.","mfa":"unclear","ai":"not-applicable","aid":"Element's privacy policy does not mention AI or machine learning training. It says nobody at Element or its processors can access encrypted data.","np":null,"note":"Check which hosting location was picked when your server was set up, and use your own domain so you can move later. Element's published prices now focus on self-hosting.","conf":"low","src":[["Element Privacy Policy","https://element.io/legal/privacy"],["Element Company information","https://element.io/legal/company-information"],["Element plans and pricing","https://element.io/en/pricing"],["Element Server Suite","https://element.io/en/server-suite"],["Element Cloud Documentation","https://ems-docs.element.io/books/element-cloud-documentation/export/html"]]},{"id":"jitsi-meet","name":"Jitsi Meet (meet.jit.si)","job":"Video meetings","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":true,"loc":"","locs":[],"hq":"US","co":"8x8, Inc.","par":null,"parc":null,"store":"Plan assumed: the free public service at meet.jit.si. 8x8 does not say where its servers are. Chat is only kept during the meeting, recordings are held for up to 24 hours until uploaded to your Dropbox, and audio and video are not stored. 8x8 stores the account that created each room.","res":"unclear","plans":null,"mfa":"unclear","ai":"unclear","aid":"The meet.jit.si privacy supplement (last updated August 2023) does not mention AI. It says 8x8 uses personal information to deliver and improve the service.","np":"Free to use.","note":"meet.jit.si is free and keeps little meeting content, but 8x8 does not say where its servers are. Since August 2023 whoever starts a meeting must sign in with Google, GitHub or Facebook.","conf":"medium","src":[["meet.jit.si Privacy Supplement","https://jitsi.org/meet-jit-si-privacy/"],["meet.jit.si Terms of Service","https://jitsi.org/meet-jit-si-terms-of-service/"],["Jitsi Meet Security & Privacy","https://jitsi.org/security/"],["Authentication on meet.jit.si","https://jitsi.org/blog/authentication-on-meet-jit-si/"],["About Jitsi","https://jitsi.org/about/"]]},{"id":"mattermost-cloud","name":"Mattermost Cloud","job":"Team chat","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Mattermost, Inc.","par":null,"parc":null,"store":"Plan assumed: Mattermost Cloud, which is now sold only through Mattermost sales as an annual subscription with a 100-user minimum. Cloud data, including messages, files, logs and backups, is stored in AWS us-east-1 in Virginia, US.","res":"yes-on-request","plans":"No published EU or UK region. Mattermost says to contact its sales team or a partner for residency outside the US, or to self-host.","mfa":"all plans","ai":"unclear","aid":"Mattermost's AI Agents connect to a language model provider that the admin configures. Whether Mattermost trains models on customer data: unknown.","np":"Nonprofit licence: 3 years of self-hosted Mattermost Professional for up to 1,000 users for US$250. Larger nonprofits are reviewed case by case, including for Cloud.","note":"Mattermost Cloud is hosted in the US and needs at least 100 paid users. The nonprofit licence covers self-hosting, which puts the data wherever you host it.","conf":"medium","src":[["Cloud data residency - Mattermost documentation","https://docs.mattermost.com/administration-guide/manage/cloud-data-residency"],["Cloud - Mattermost documentation","https://docs.mattermost.com/product-overview/cloud-subscriptions"],["Mattermost Pricing","https://mattermost.com/pricing/"],["Multi-factor authentication - Mattermost documentation","https://docs.mattermost.com/administration-guide/onboard/multi-factor-authentication.html"],["Bulk export data - Mattermost documentation","https://docs.mattermost.com/administration-guide/manage/bulk-export-tool.html"],["Non-Profit Subscriptions - Mattermost documentation","https://docs.mattermost.com/product-overview/non-profit-subscriptions.html"],["Agents admin guide - Mattermost documentation","https://docs.mattermost.com/administration-guide/configure/agents-admin-guide.html"],["mattermost/mattermost on GitHub","https://github.com/mattermost/mattermost"]]},{"id":"calendly","name":"Calendly","job":"Booking and scheduling","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Calendly LLC","par":null,"parc":null,"store":"US. Calendly says it stores user and invitee data in US data centres run by Google Cloud and Amazon Web Services, on all plans.","res":"no","plans":"Plan assumed: all plans (Free, Standard, Teams). Calendly's help page says the storage statement applies to all plans.","mfa":"all plans","ai":"no","aid":"Calendly's security page says: 'Calendly does not sell customer data or use customer data to train AI models. Third-party AI providers are prohibited from using customer data to train their models.' Checked 29 September 2026.","np":"Unknown. Calendly's pricing page only says to contact sales about not-for-profit pricing.","note":"Calendly holds your bookings and your invitees' details in the US, so tell people who book with you. You can export your meetings and your contacts as CSV files, but Calendly's help pages do not describe a single full export, so check what you need is covered. Two-factor login is available on all plans, so switch it on for every account. Calendly's pricing page only says to contact sales about not-for-profit pricing, so ask before you assume a discount.","conf":"medium","src":[["Data storage and international data transfers","https://calendly.com/help/data-storage-and-international-data-transfers"],["Calendly security","https://calendly.com/security"],["Data Processing Addendum","https://calendly.com/legal/data-processing-addendum"],["Calendly pricing","https://calendly.com/pricing"],["How to set up two-factor authentication (2FA)","https://calendly.com/help/how-to-set-up-two-factor-authentication-2fa"],["Tracking and reporting (export meeting data)","https://calendly.com/help/tracking-and-reporting"],["How to import and export contacts","https://calendly.com/help/how-to-import-and-export-contacts"]]}]},{"g":"AI tools","items":[{"id":"chatgpt","name":"ChatGPT","job":"AI chat assistant","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"OpenAI","par":null,"parc":null,"store":"Not stored in the UK or EU by default. Personal plans and ChatGPT Business have no data residency option. ChatGPT Enterprise and Edu customers can choose to store content at rest in Europe or the UK.","res":"yes-some-plans","plans":"ChatGPT Enterprise, ChatGPT Edu and eligible API customers (Europe and UK storage at rest; expanded to more regions in November 2025). Not ChatGPT Business, Free or Plus.","mfa":"all plans","ai":"depends-on-plan","aid":"Free, Go, Plus and Pro (personal): chats are used to train models by default. Opt out by turning off 'Improve the model for everyone' in Settings > Data controls, or via the OpenAI Privacy Portal ('Do not train on my content'). Giving thumbs up or down feedback can still send that whole conversation for training. ChatGPT Business (formerly Team), Enterprise, Edu and the API: not used for training by default; an organisation can opt in.","np":"OpenAI for Nonprofits: ChatGPT Business Standard seats at $8 per user per month (annual) or $10 (monthly) after Goodstack verification; up to 75% off Enterprise for larger nonprofits via sales.","note":"Personal ChatGPT accounts train on your chats unless each person turns this off, so staff should not use personal accounts for charity work. ChatGPT Business does not train on your data but stores it outside the UK and EU; only Enterprise offers UK or European storage.","conf":"high","src":[["How your data is used to improve model performance (OpenAI Help Center)","https://help.openai.com/en/articles/5722486-how-your-data-is-used-to-improve-model-performance"],["Business data privacy, security, and compliance (OpenAI)","https://openai.com/business-data/"],["Expanding data residency access to business customers worldwide (OpenAI)","https://openai.com/index/expanding-data-residency-access-to-business-customers-worldwide/"],["Introducing data residency in Europe (OpenAI)","https://openai.com/index/introducing-data-residency-in-europe/"],["Enterprise privacy at OpenAI","https://openai.com/enterprise-privacy/"],["How do I export my ChatGPT history and data? (OpenAI Help Center)","https://help.openai.com/en/articles/7260999-how-do-i-export-my-chatgpt-history-and-data"],["Does ChatGPT support multi-factor authentication? (OpenAI Help Center)","https://help.openai.com/en/articles/7967234-does-chatgpt-support-multi-factor-authentication-mfa"],["OpenAI for Nonprofits (OpenAI Help Center)","https://help.openai.com/en/articles/9359041-openai-for-nonprofits"]]},{"id":"claude","name":"Claude","job":"AI chat assistant","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Anthropic PBC","par":null,"parc":null,"store":"Stored in the US on all Claude plans. Processing may be routed to the US, Europe, Asia and Australia. No UK or EU storage option for Claude Team or Enterprise.","res":"no","plans":null,"mfa":"unclear","ai":"depends-on-plan","aid":"Free, Pro and Max (consumer): since 28 August 2025 each user chooses whether chats and coding sessions are used for training; existing users had to decide by 8 October 2025. If allowed, data is kept for up to five years; if not, the usual 30-day retention applies. Change it any time in Settings > Privacy (model improvement setting); incognito chats are never used. Team, Enterprise, API, Government and Education: not used for training by default.","np":"Claude for Nonprofits: Team plan at $8 per user per month and Enterprise at $10, verified through Goodstack; Anthropic's page lists US 501(c)(3) organisations as eligible, so check whether UK or EU charities qualify.","note":"Personal Claude accounts may use chats for training if the person allowed it in the 2025 privacy prompt, so check Settings > Privacy. All Claude data is stored in the US, with no UK or EU storage option on any plan.","conf":"high","src":[["Updates to Consumer Terms and Privacy Policy (Anthropic)","https://www.anthropic.com/news/updates-to-our-consumer-terms"],["Is my data used for model training? Consumer (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/10023580-is-my-data-used-for-model-training"],["Is my data used for model training? Commercial (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/7996868-is-my-data-used-for-model-training"],["Where are your servers located? (Anthropic Privacy Center)","https://privacy.claude.com/en/articles/7996890-where-are-your-servers-located-do-you-host-your-models-on-eu-servers"],["Data residency (Claude Platform Docs)","https://platform.claude.com/docs/en/manage-claude/data-residency"],["Export your Claude data (Claude Help Center)","https://support.claude.com/en/articles/9450526-how-can-i-export-my-claude-data"],["Getting started with Claude for Nonprofits (Claude Academy)","https://academy.claude.com/tutorials/getting-started-with-claude-for-nonprofits"]]},{"id":"google-gemini","name":"Google Gemini","job":"AI chat assistant","k":"AI tool","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC","par":"Alphabet Inc.","parc":"US","store":"Not stated for personal accounts or ordinary Workspace plans. Workspace admins can keep Gemini data in the EU only on Enterprise Plus, Frontline Plus, Education editions or Assured Controls add-ons. The UK is not offered as a separate region.","res":"yes-some-plans","plans":"Workspace Enterprise Plus and Frontline Plus (EU processing and storage), Education Standard and Plus (EU storage only), Assured Controls add-ons. Not Workspace for Nonprofits, Business Starter or personal accounts.","mfa":"all plans","ai":"depends-on-plan","aid":"Personal Google account (Gemini app): with Keep Activity on, which is the default, chats and uploads are used to improve Google's services, including training generative AI models, and a subset is reviewed by humans (kept up to 3 years, detached from the account). Turn off Keep Activity or use Temporary chats; chats are then kept for 72 hours and not used for training, unless you send feedback. Gemini in Google Workspace (work or school account): customer data is not used to train models without permission and is not human reviewed.","np":"Google for Nonprofits: Gemini app and Gemini Notebook are included in the no-cost Google Workspace for Nonprofits plan, with up to 75% off advanced Workspace editions for eligible nonprofits.","note":"Staff using Gemini on personal Google accounts have their chats used for training and possibly read by reviewers unless they turn off Keep Activity. Use Gemini through the charity's Workspace account, where your data is not used for training.","conf":"medium","src":[["Gemini Apps Privacy Hub (Google)","https://support.google.com/gemini/answer/13594961"],["Generative AI in Google Workspace Privacy Hub","https://knowledge.workspace.google.com/admin/generative-ai/generative-ai-in-google-workspace-privacy-hub"],["Data regions support for the Gemini app (Google Workspace Updates)","https://workspaceupdates.googleblog.com/2026/06/gemini-app-data-regions-support.html"],["Data regions support for Gemini features in Google Workspace (Google Workspace Updates)","https://workspaceupdates.googleblog.com/2025/06/data-regions-support-for-gemini-features-in-google-workspace.html"],["Choose a geographic location for your data (Google Workspace Admin Help)","https://knowledge.workspace.google.com/admin/compliance/choose-a-geographic-location-for-your-data"],["The best of Google AI is now included in Workspace (Google for Nonprofits Help)","https://support.google.com/nonprofits/answer/15873832"],["Turn on 2-Step Verification (Google Account Help)","https://support.google.com/accounts/answer/185839"]]},{"id":"microsoft-365-copilot","name":"Microsoft 365 Copilot and Copilot Chat","job":"AI assistant in Office","k":"AI tool","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":false,"loc":"GB","locs":["GB","EU"],"hq":"US","co":"Microsoft Corporation","par":null,"parc":null,"store":"Prompts and responses are stored in the organisation's Microsoft 365 tenant (Exchange), so they follow the tenant's data location. EU tenants are covered by the EU Data Boundary, with exceptions. UK in-country processing was promised from late 2025, later adjusted to the end of 2026.","res":"yes-default","plans":"Any Microsoft 365 work or school tenant located in the UK or EU, including Copilot Chat included with Microsoft 365 subscriptions.","mfa":"all plans","ai":"no","aid":"For work or school (Entra ID) accounts, prompts, responses and data accessed through Microsoft Graph are not used to train foundation models, in both Microsoft 365 Copilot and Copilot Chat with enterprise data protection (green shield). This does not cover the consumer Microsoft Copilot app used with a personal Microsoft account.","np":"Copilot Chat is included at no extra cost with eligible Microsoft 365 subscriptions, including nonprofit plans (Business Basic grant for up to 300 users; Business Premium at $5.50 per user per month). Microsoft's nonprofit pricing page lists no separate nonprofit price for Microsoft 365 Copilot Business.","note":"Since 17 April 2026 Microsoft can process EU tenants' Copilot requests outside the EU at busy times (flex routing) unless an admin turns this off. Anthropic models and Bing web search in Copilot also sit outside the EU Data Boundary, so check these settings in the Microsoft 365 admin centre.","conf":"medium","src":[["Data, Privacy, and Security for Microsoft 365 Copilot (Microsoft Learn)","https://learn.microsoft.com/en-us/microsoft-365/copilot/microsoft-365-copilot-privacy"],["Microsoft Copilot Chat privacy and protections (Microsoft Learn)","https://learn.microsoft.com/en-us/copilot/privacy-and-protections"],["Microsoft offers in-country data processing to 15 countries (Microsoft Copilot blog, 4 Nov 2025)","https://www.microsoft.com/en-us/copilot/blog/2025/11/04/microsoft-offers-in-country-data-processing-to-15-countries-to-strengthen-sovereign-controls-for-microsoft-365-copilot/"],["Microsoft 365 Copilot Flex Routing (ChangePilot)","https://changepilot.cloud/blog/microsoft-365-copilot-flex-routing-eu-data-boundary-mc1269223"],["Data Residency for Microsoft 365 Copilot and Copilot Chat (Microsoft Learn)","https://learn.microsoft.com/en-us/microsoft-365/enterprise/m365-dr-service-copilot?view=o365-worldwide"],["Microsoft 365 plans for nonprofits (Microsoft)","https://www.microsoft.com/en-us/microsoft-365/business/nonprofit-plans-and-pricing"],["Security defaults in Microsoft Entra ID (Microsoft Learn)","https://learn.microsoft.com/en-us/entra/fundamentals/security-defaults"]]},{"id":"mistral-le-chat","name":"Mistral Vibe (was Le Chat)","job":"AI chat assistant","k":"AI tool","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"FR","co":"Mistral AI SAS","par":null,"parc":null,"store":"Hosted in the EU by default. Some features may transfer data temporarily outside the EU to listed subprocessors; Enterprise customers can switch some of those features off.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"depends-on-plan","aid":"Free: chats are used for training by default; opt out in the admin or privacy settings ('Allow your interactions to be used to train our models') or in the mobile app under Data & Account Controls. Pro: Mistral's pages conflict (the help centre says users are not opted out by default, the product docs say Pro is not trained on by default), so check the toggle. Team: admins can switch training off for the whole organisation; the docs say it is off by default. Enterprise: opted out by default. Thumbs up or down feedback can be used for training on any plan.","np":null,"note":"Le Chat was renamed Vibe on 12 August 2026; accounts and data carried over. Data is hosted in the EU, but check the training toggle in the admin panel, especially on Free and Pro.","conf":"medium","src":[["Do you use my user data to train your AI models? (Mistral Help Center)","https://help.mistral.ai/en/articles/347617-do-you-use-my-user-data-to-train-your-artificial-intelligence-models"],["Can I opt out of my input or output data being used for training? (Mistral Help Center)","https://help.mistral.ai/en/articles/455207-can-i-opt-out-of-my-input-or-output-data-being-used-for-training"],["Privacy (Mistral docs)","https://docs.mistral.ai/admin/security-access/privacy"],["Where do you store my data? (Mistral Help Center)","https://help.mistral.ai/en/articles/347629-where-do-you-store-my-data-or-my-organization-s-data"],["How do I export my data from Vibe? (Mistral Help Center)","https://help.mistral.ai/en/articles/347623-how-do-i-export-my-data-from-vibe"],["Le Chat is now Vibe (Mistral Help Center)","https://help.mistral.ai/en/articles/682992-le-chat-is-now-vibe"],["As an admin on Team plan or Enterprise, do I have company-wide controls? (Mistral Help Center)","https://help.mistral.ai/en/articles/455796-as-an-admin-on-team-plan-or-enterprise-do-i-have-company-wide-controls"],["Pricing (Mistral AI)","https://mistral.ai/pricing"]]},{"id":"otter-ai","name":"Otter.ai","job":"Meeting transcription","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Otter.ai, Inc.","par":null,"parc":null,"store":"US by default. Otter uses Amazon Web Services in the United States and relies on the Data Privacy Framework and Standard Contractual Clauses for UK and EU transfers. Otter does not list a UK or EU storage option.","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"Otter trains its own AI on de-identified audio recordings and on transcripts, which may contain personal information, on all plans. Human review of recordings for training needs the user's permission, which can be changed in account settings. Only Enterprise customers can also opt out of the de-identified data use.","np":null,"note":"Otter trains its AI on de-identified recordings and transcripts of your meetings, and only Enterprise customers can opt out. Data is stored in the US.","conf":"medium","src":[["Privacy Policy (Otter.ai)","https://otter.ai/privacy-policy"],["Security (Otter.ai)","https://otter.ai/security"],["Pricing (Otter.ai)","https://otter.ai/pricing"],["Otter Help Center export article","https://help.otter.ai/hc/en-us/articles/360047733634-Otter-data-privacy"]]},{"id":"fireflies-ai","name":"Fireflies.ai","job":"Meeting transcription","k":"AI tool","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Fireflies.ai Corp.","par":null,"parc":null,"store":"Stored on servers in the United States and other countries. Enterprise customers can buy private storage at a location they choose.","res":"yes-some-plans","plans":"Enterprise (private storage)","mfa":"unclear","ai":"no","aid":"Fireflies says it does not use personal information or meeting content for AI model training and contractually bars its AI vendors from training on it, with zero data retention at those vendors. Applies to all plans.","np":null,"note":"Fireflies does not train AI on your meetings, but recordings and transcripts are stored in the US unless you pay for Enterprise private storage. Tell meeting guests the notetaker is recording.","conf":"medium","src":[["Privacy Policy (Fireflies.ai)","https://fireflies.ai/privacy-policy"],["Security (Fireflies.ai)","https://fireflies.ai/security"],["Pricing (Fireflies.ai)","https://fireflies.ai/pricing"],["How to Download Transcripts, Summaries, and Meeting Recordings (Fireflies Knowledge Base)","https://guide.fireflies.ai/hc/en-us/articles/360020247558"]]},{"id":"zoom-ai-companion","name":"Zoom AI Companion","job":"Meeting summaries","k":"AI tool","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Zoom Communications, Inc.","par":null,"parc":null,"store":"Follows the region the Zoom account is hosted in. Hosting region for new UK or EU accounts: unknown. Admins on Pro and above can choose Germany for recordings and some content, but out-of-meeting chat and account data stay in the provisioned region. The UK is not in the storage list.","res":"yes-some-plans","plans":"Pro and above can pick Germany for recordings, transcripts and some content; accounts hosted in the EU use Zoom-managed models (ZM+) to respect data residency.","mfa":"unclear","ai":"no","aid":"Zoom says it does not use audio, video, chat, screen sharing, attachments or other communications-like content to train its own or third-party AI models. For US-hosted accounts AI Companion sends content to third-party models (Anthropic, OpenAI, Google) under zero data retention terms; admins can ask Zoom Support for Zoom-hosted-only processing (ZMO).","np":"Zoom gives 50% off Workplace Pro and Business annual plans to verified nonprofits (US 501(c)(3) or an international equivalent recognised by the regulator, operating budget of $10 million or less), verified through Goodstack. Whether this covers AI Companion on its own: unknown.","note":"Zoom does not train AI on your meeting content, but by default AI Companion may send it to third-party AI providers for processing. Ask Zoom which region your account is hosted in and which AI processing option applies.","conf":"medium","src":[["Zoom Privacy Statement","https://www.zoom.com/en/trust/privacy/privacy-statement/"],["Models, Processing, Storage, and Usage (Zoom AI whitepaper)","https://library.zoom.com/ai/ai-whitepaper/models-processing-storage-and-usage.md"],["Data Governance and Privacy (Zoom AI whitepaper)","https://library.zoom.com/ai/ai-whitepaper/data-governance-and-privacy.md"],["Managing Data & Storage location (Zoom Support)","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0066473"],["Subscribing to Zoom as a nonprofit organization (Zoom Support)","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0080298"],["Viewing stored chat messages in the Chat history report (Zoom Support)","https://support.zoom.com/hc/en/article?id=zm_kb&sysparm_article=KB0061552"]]}]},{"g":"Supporters and fundraising","items":[{"id":"mailchimp","name":"Mailchimp","job":"Newsletter","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"The Rocket Science Group LLC (Intuit Mailchimp)","par":"Intuit Inc.","parc":"US","store":"US by default for all customers (assumed plan: Essentials or Standard). No EU or UK hosting option. Transfers rely on the EU-US Data Privacy Framework and UK Extension, with SCCs as fallback.","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"Terms section 30 lets Mailchimp use generative AI Inputs and Outputs, including Customer Data, for machine learning to develop the AI model and services. Section 17 lets it aggregate and anonymise campaign content for its own use. The terms point to data preferences in account settings but do not describe a full opt-out.","np":"15% off marketing plans. Non-US nonprofits can apply with their website; request before buying, as it is not applied retroactively.","note":"Supporter data is stored in the US and there is no UK or EU hosting option. Check the data preferences in your account settings if you use the AI writing features.","conf":"high","src":[["Mailchimp and European Data Transfers","https://mailchimp.com/help/mailchimp-european-data-transfers/"],["Mailchimp Data Security and Privacy","https://mailchimp.com/about/security/"],["Set Account Security Options","https://mailchimp.com/help/set-account-security-options/"],["Mailchimp's Standard Terms of Use","https://mailchimp.com/legal/terms/"],["Export and Back Up Account Data","https://mailchimp.com/help/export-back-up-data/"],["About the Nonprofit Discount","https://mailchimp.com/help/about-nonprofit-discount/"]]},{"id":"brevo","name":"Brevo","job":"Newsletter and CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"FR","locs":["FR","DE","BE"],"hq":"FR","co":"Sendinblue SAS (trading as Brevo)","par":null,"parc":null,"store":"EU for all customers (assumed plan: Starter). Hosted with OVH in France and Germany and Google Cloud in Belgium.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"yes","aid":"Terms allow Brevo to use Content and Usage Data to train its AI features, limited to improving the services, in particular fraud, phishing and spam prevention and security. Other AI features can be managed in the Control Center, but fraud and spam detection cannot be switched off. Third-party AI providers only process data to provide the feature.","np":"20% off any paid monthly or yearly plan for verified nonprofits; contact support with proof of status.","note":"Data is held in the EU by default. Brevo can use your content to train its anti-spam and fraud AI, and that cannot be switched off.","conf":"high","src":[["Data storage location","https://help.brevo.com/hc/en-us/articles/360001005510-Data-storage-location"],["Data Security and Privacy","https://www.brevo.com/features/data-security/"],["Secure your account with two-factor authentication (2FA)","https://help.brevo.com/hc/en-us/articles/360021203440-Secure-your-account-with-two-factor-authentication-2FA"],["Brevo Terms of Service","https://www.brevo.com/legal/termsofuse/"],["Export your contacts from Brevo","https://help.brevo.com/hc/en-us/articles/5310065850642-Export-your-contacts-from-Brevo"],["Brevo for NGOs","https://www.brevo.com/company/ngos/"]]},{"id":"cleverreach","name":"CleverReach","job":"Newsletter","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE","EU"],"hq":"DE","co":"CleverReach GmbH & Co. KG","par":"CRASH group of companies","parc":"DE","store":"Germany and the EU for all customers (assumed plan: Basic). The supplier says servers are exclusively in Germany and the EU.","res":"yes-default","plans":"All plans","mfa":"some plans","ai":"unclear","aid":"The AI Content Generator sends your prompt to OpenAI. CleverReach does not say whether prompts are used for training or where OpenAI processes them. It is an optional feature on Basic and above. Training with recipient data: unknown.","np":"Discount for nonprofits on request; amount not published.","note":"Recipient data stays in Germany and the EU. Full two-factor login is listed only on Enterprise; smaller plans can switch on an emailed PIN code at login under Settings.","conf":"medium","src":[["Data Security - CleverReach","https://www.cleverreach.com/en/data-security/"],["GDPR-compliant newsletter tool Made in Germany","https://www.cleverreach.com/en/gdpr-compliant-newsletter-tool/"],["Privacy Policy - CleverReach","https://www.cleverreach.com/en/privacy-policy/"],["Pricing","https://www.cleverreach.com/en/plans-and-pricing/"],["Secure login with PIN code","https://support.cleverreach.com/hc/en-us/articles/17799104835602-Secure-login-with-PIN-code"],["AI Content Generator for Beautiful Email Copy","https://www.cleverreach.com/en/newsletter-tool/creating-and-designing-newsletters/ai-content-generator/"],["Export of adresses of a segment","https://support.cleverreach.com/hc/en-us/articles/360035176194-Export-of-adresses-of-a-segment"]]},{"id":"beacon-crm","name":"Beacon CRM","job":"Supporter CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"GB","locs":["GB","IE"],"hq":"GB","co":"Beacon (beaconcrm.org)","par":null,"parc":null,"store":"UK by default (assumed plan: Starter). Trust page says data is hosted exclusively in the UK on AWS; the sub-processor list names AWS London and Ireland and Google Cloud London for core storage.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"Beacon says Beacon AI cannot access your data and does not use it to train public AI models. The AI provider behind Beacon AI is not named in the sub-processor list.","np":null,"note":"Data is held in the UK. In late July 2026 attackers copied Beacon's customer database backups, affecting over 1,000 charities, so check what Beacon has told you and whether you have acted on it.","conf":"high","src":[["Beacon Trust","https://www.beaconcrm.org/trust"],["Beacon Sub-processors","https://www.beaconcrm.org/legal/sub-processors"],["Export your data","https://guide.beaconcrm.org/en/articles/5717571-export-your-data"],["Beacon Pricing and Plans","https://www.beaconcrm.org/pricing"],["Over 1,000 Charities Hit by Beacon CRM Data Breach","https://www.securityweek.com/over-1000-charities-hit-by-beacon-crm-data-breach/"],["Beacon CRM cyber incident: what Scottish charities should do now","https://scvo.scot/p/106392/2026/08/04/beacon-crm-cyber-incident-what-scottish-charities-should-do-now"]]},{"id":"salesforce-nonprofit-cloud","name":"Salesforce Nonprofit","job":"Supporter CRM","k":"Software","w":"Don't know","b":"Elsewhere","x":"Yes","o":false,"loc":"","locs":[],"hq":"US","co":"Salesforce, Inc.","par":null,"parc":null,"store":"Depends on the region the org is provisioned in (assumed plan: Power of Us donated Enterprise Edition). Hyperforce runs in the UK, Germany and other countries, and data is generally stored in the country where the org is located. The Hyperforce EU Operating Zone adds stronger EU and Swiss residency commitments but is not offered for the UK. Generative AI features may route data to LLM providers such as OpenAI or Azure.","res":"yes-on-request","plans":"Hyperforce orgs provisioned in a UK or EU region; EU Operating Zone for EU and Swiss customers","mfa":"all plans","ai":"yes","aid":"Salesforce says generative AI features are not trained on customer data, but predictive Einstein features can use org data for global models. Since the Spring 2026 release admins can switch this off under Setup > Opt Out of Customer Data Access; most orgs start opted in.","np":"Power of Us programme: 10 donated Enterprise Edition licences of Agentforce Nonprofit (or Sales and Service Cloud) for eligible nonprofits.","note":"Check your instance location on my.trust.salesforce.com, because storage depends on where your org was set up. Ask your admin to review the Opt Out of Customer Data Access setting, which starts switched to allow data use.","conf":"medium","src":[["Hyperforce: Public Cloud Infrastructure","https://www.salesforce.com/uk/platform/public-cloud-infrastructure/"],["Hyperforce: European Union Public Cloud Infrastructure","https://www.salesforce.com/uk/platform/data-residence-eu-oz/"],["Salesforce Infrastructure and Sub-processors","https://www.salesforce.com/en-us/wp-content/uploads/sites/4/documents/legal/misc/salesforce-infrastructure-and-subprocessors.pdf"],["Where is my Salesforce instance located?","https://help.salesforce.com/s/articleView?id=000396845&language=en_US&type=1"],["Debunking Myths: Salesforce Einstein and Agentforce","https://www.salesforce.com/blog/debunking-myths-salesforce-einstein-and-agentforce/"],["Salesforce AI Data Sharing Opt Out: What Nonprofits, Associations and Foundations Need to Know","https://fionta.com/insights/salesforce-ai-data-sharing-opt-out-what-nonprofits-associations-and-foundations-need-to-know/"],["Salesforce Data Export FAQ","https://help.salesforce.com/s/articleView?id=000383962&language=en_US&type=1"],["How to Prepare for Salesforce's Mandatory MFA Changes in 2026","https://www.salesforceben.com/how-to-prepare-for-salesforces-mandatory-mfa-changes-in-2026/"],["The State of Salesforce Nonprofit Offerings in 2026","https://www.salesforceben.com/the-state-of-salesforce-nonprofit-offerings-in-2026/"]]},{"id":"civicrm","name":"CiviCRM","job":"Supporter CRM","k":"Software","w":"Don't know","b":"Elsewhere","x":"Yes","o":true,"loc":"","locs":[],"hq":"US","co":"CiviCRM LLC","par":null,"parc":null,"store":"Depends entirely on the host (assumed: hosted by a CiviCRM partner). Self-hosted or partner-hosted data sits wherever that server is. CiviCRM's own Spark hosting lets you choose North America or Europe.","res":"yes-on-request","plans":"Any host with UK or EU servers; Spark with the Europe option","mfa":"unclear","ai":"not-applicable","aid":"Core CiviCRM has no supplier AI service that receives your data. Check any AI extensions or host services you add.","np":"Free open-source software (AGPL 3). You pay for hosting and support; Spark hosting starts at about USD 15 a month.","note":"Where your data lives and whether two-factor login is available depend on your hosting partner and the website system CiviCRM runs on. Ask your host where the servers are and whether you can get a full database copy.","conf":"medium","src":[["License","https://civicrm.org/about/license"],["CiviCRM","https://civicrm.org/"],["Spark - CiviCRM","https://civicrm.com/spark/"],["Hosting - CiviCRM Installation Guide","https://docs.civicrm.org/installation/en/latest/planning/hosting/"],["Exporting - CiviCRM User Guide","https://docs.civicrm.org/user/en/latest/common-workflows/exporting-your-contacts/"],["Login Security - CiviCRM Documentation","https://docs.civicrm.org/loginsecurity/en/latest/"]]},{"id":"donorfy","name":"Donorfy","job":"Supporter CRM","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"IE","locs":["IE"],"hq":"GB","co":"Donorfy","par":"The Access Group","parc":"GB","store":"EU by default (assumed plan: Starter). Hosted on Microsoft Azure North Europe in Dublin, Ireland. Enterprise can use private cloud hosting.","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"no","aid":"Donorfy is being linked to The Access Group's Access Evo AI features. Access says Evo AI has zero data retention for training and inputs are never used to improve models. Evo features were switched on automatically from 17 November 2025 and admins can turn them off.","np":null,"note":"Data is held in Ireland. A full export with all fields and attachments costs extra, so ask for the price before you decide to leave.","conf":"medium","src":[["Donorfy Security","https://donorfy.com/security"],["Pricing","https://donorfy.com/pricing"],["Downloading your data","https://donorfy.com/downloading-data"],["The Access Group to Acquire Charity CRM Provider Donorfy","https://www.theaccessgroup.com/en-gb/about/news/the-access-group-to-acquire-charity-crm-provider-donorfy/"],["Building a new Donorfy API: What It Means for You","https://www.theaccessgroup.com/en-gb/blog/nfp-building-a-new-donorfy-api-what-it-means-for-you/"],["Access Evo Platform: FAQ","https://help-accessevo.theaccessgroup.com/en/articles/15937010-access-evo-platform-faq"]]},{"id":"hubspot","name":"HubSpot","job":"CRM and email marketing","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"US","co":"HubSpot, Inc.","par":null,"parc":null,"store":"Set at sign-up by the IP address location (assumed plan: free CRM or Starter). HubSpot has an EU data centre in Germany; accounts started in the US data centre can be moved to the EU on any plan. HubSpot does not state where UK sign-ups go. Usage data and some processing still go to the US.","res":"yes-on-request","plans":"All plans (EU data centre by sign-up location or migration)","mfa":"all plans","ai":"yes","aid":"HubSpot uses customer data such as CRM activity to train its models by default. Super Admins can switch off 'AI Model Training' under Settings > AI > Access. Opt-out applies from then on only. Accounts with Sensitive Data enabled are opted out.","np":"40% off Professional and Enterprise for new annual customers, but HubSpot's page limits it to nonprofits registered in North America, Australia and New Zealand. Starter is excluded.","note":"Check Account defaults to see which data centre your account uses, as UK sign-ups may land in the US. HubSpot trains AI on your CRM data unless a Super Admin switches it off.","conf":"medium","src":[["HubSpot Cloud Infrastructure and Data Hosting FAQ","https://knowledge.hubspot.com/account-security/hubspot-cloud-infrastructure-and-data-hosting-frequently-asked-questions"],["Migrate account data to another regional data center","https://knowledge.hubspot.com/account-management/migrate-your-account-data-to-hubspots-eu-data-center"],["Two-factor authentication","https://knowledge.hubspot.com/account/two-factor-authentication-faq"],["Opt out of HubSpot's machine learning data use","https://knowledge.hubspot.com/account-management/hubspot-machine-learning-data"],["Export records","https://knowledge.hubspot.com/import-and-export/export-records"],["HubSpot for Nonprofits","https://www.hubspot.com/nonprofits"]]},{"id":"foreninglet","name":"ForeningLet","job":"Association and membership administration","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"DK","co":"ForeningLet ApS","par":null,"parc":null,"store":"EU only. ForeningLet's data processing agreement says processing takes place 'inden for EUs grænser' (within the EU) and that personal data is never transferred to third countries. Amazon (Ireland) hosts the IT infrastructure. The agreement does not name a country.","res":"yes-default","plans":"Base package from 99 kr a month for up to 100 members, before VAT (checked 29 September 2026). The data processing terms apply to all customers.","mfa":"all plans","ai":"unclear","aid":"ForeningLet has an AI assistant that searches the user guide and, depending on user rights, looks up members and invoices. The user guide says: 'Ingen data sendes videre til tredjepart' (no data is sent to third parties) and 'Al behandling kører på servere hos ForeningLet' (all processing runs on ForeningLet's servers). AI model training: unknown.","np":"Unknown.","note":"ForeningLet offers a data processing agreement (databehandleraftale) and says data stays in the EU, hosted by Amazon in Ireland. It holds your members' personal data, so check that your organisation has accepted the agreement and that one person is not the only administrator. You can export member lists to Excel or CSV, so do that regularly. Two-factor login is available: an administrator switches it on under Opsætning, Forening, To-faktor-login, and it then applies to all administrators, with a one-time code sent by email.","conf":"medium","src":[["Databehandleraftale (ForeningLet)","https://foreninglet.dk/main/dpaexample"],["Priser (ForeningLet)","https://web.foreninglet.dk/priser/"],["Priser, modules and fees (ForeningLet)","https://foreninglet.dk/main/price"],["ForeningLet brugervejledning (import and export of members)","https://docs.foreninglet.dk/documentation/danish/ForeningLet.pdf"],["AI-assistent (ForeningLet brugervejledning)","https://docs.foreninglet.dk/documentation/danish/ai_assistant.html"],["Grundlæggende opsætning, to-faktor-login (ForeningLet brugervejledning)","https://docs.foreninglet.dk/documentation/danish/basic_configuration.html"]]},{"id":"membersite","name":"Membersite","job":"Association and membership administration (member self-service)","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Don't know","o":false,"loc":"DK","locs":["DK"],"hq":"DK","co":null,"par":"EG A/S","parc":"DK","store":"Denmark. EG says its Membercare membership system, which includes the Membersite self-service portal, is 'udviklet, hostet og GDPR-sikret i Danmark' (developed, hosted and GDPR-secured in Denmark). The same page also says 'udviklet og hosted i norden' (Nordic), so the exact country is worth confirming.","res":"unclear","plans":"Membersite is the member self-service part of EG Membercare (packages Basis, Udvidet and Premium). EG prices Membercare by number of members and chosen modules, on a quote. Plan assumed: any Membercare package.","mfa":"unclear","ai":"unclear","aid":"Unknown.","np":null,"note":"Membersite was made by Groupcare, which EG bought in November 2023, and is now sold as part of EG Membercare. EG says the system is hosted in Denmark. Data processing agreement (databehandleraftale): unknown, so ask EG for it. The price is by quote. Ask how you get your member data out if you leave, and whether administrators can use two-step login. Export terms, two-step login and AI training: unknown.","conf":"medium","src":[["Medlemsadministration til organisationer (EG Membercare)","https://egsoftware.com/dk/medlemsorganisationer/eg-membercare"],["EG Membercare pris","https://egsoftware.com/dk/medlemsorganisationer/eg-membercare/pris"],["EG køber Groupcare","https://egsoftware.com/dk/ressource/eg-koeber-groupcare"],["EG Trust Center","https://egsoftware.com/global/trust-center"],["Handelsbetingelser for MemberCare og MemberSite (a customer's page, Dansk Friskoleforening; names Groupcare as data processor)","https://www.friskolerne.dk/om-os/privatlivspolitik/handelsbetingelser-for-dansk-friskoleforenings-medlemssystemer-membercare-og-membersite"]]}]},{"g":"Donations, payments and events","items":[{"id":"justgiving","name":"JustGiving","job":"Online fundraising pages","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"GB","co":"Giving.com Limited (JustGiving, UK); MyCharity Limited (Ireland/EEA)","par":"Blackbaud, Inc.","parc":"US","store":"Not stated. The privacy policy says some personal data may be stored outside the UK, EU or EEA, and JustGiving is covered by Blackbaud's EU-US Data Privacy Framework certification.","res":"unclear","plans":null,"mfa":"all plans","ai":"unclear","aid":"The privacy policy says JustGiving uses machine learning and analytics to make inferences about users (donors and fundraisers) to tailor content, and users can opt out. It does not say whether charity or donor data trains AI models. Charity account data: unknown.","np":"Built for charities. Start plan has no monthly fee; Grow plan is £15 or £39 a month plus VAT depending on income. No platform fee on donations; card processing 1.9% + 30p; 5% fee on Gift Aid claimed.","note":"JustGiving and your charity are separate data controllers for donor data, so donors' details sit in JustGiving's own system as well as yours. It does not say where that data is stored, so ask Blackbaud if location matters to you.","conf":"medium","src":[["JustGiving Privacy Policy v30","https://www.justgiving.com/about/info/privacy-policy/privacy-policy-v30"],["Charity Fundraising Pricing Plans","https://www.justgiving.com/for-charities/pricing"],["Understanding your donation payment reports","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14505672461329-Understanding-your-donation-payment-reports"],["Logging in with your Blackbaud ID and Multi Factor Authentication","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14481897979281-Logging-in-with-your-Blackbaud-ID-and-Multi-Factor-Authentication"],["What is GDPR? (UK only)","https://justgiving-charitysupport.zendesk.com/hc/en-us/articles/14508528500753-What-is-GDPR-UK-only"]]},{"id":"enthuse","name":"Enthuse","job":"Branded donations and events","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"GB","locs":["GB"],"hq":"GB","co":"Online Giving Ltd (trading as Enthuse)","par":null,"parc":null,"store":"UK hosting on Microsoft Azure and AWS","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"unclear","aid":"The privacy notice does not mention AI, machine learning or model training. Opt-out setting: unknown.","np":"Charity-only product. 0% platform fee; monthly subscriptions from £0 (mass participation) to £39.99; payment fee 1.9% + 30p; 5% Gift Aid fee.","note":"Enthuse says it hosts in the UK and requires two-step verification for all admin users. Check which monthly package you are on, because features and fees differ by product.","conf":"high","src":[["Security and data - Enthuse","https://enthuse.com/security-and-data/"],["Privacy Notice - Enthuse","https://enthuse.com/privacy/"],["Pricing - Enthuse","https://enthuse.com/pricing/"],["2 Step Verification (2SV) FAQs","https://help.enthuse.com/en/articles/6842466-2-step-verification-2sv-faqs"],["Accessing and Understanding your Payment Report","https://help.enthuse.com/en/articles/11728518-accessing-and-understanding-your-payment-report"],["Importing from Enthuse (Beacon CRM)","https://guide.beaconcrm.org/en/articles/6519337-importing-from-enthuse"]]},{"id":"stripe","name":"Stripe","job":"Card payments","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"IE","co":"Stripe Payments Europe, Ltd. (contracting entity for UK and EEA); Stripe Technology Company Limited (data controller outside the Americas)","par":"Stripe, Inc.","parc":"US","store":"Transferred to other countries, including the US and India. UK or EU storage option for ordinary accounts: unknown.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"The privacy policy (updated April 2026) lists training AI models to power services and prevent fraud. Stripe's Payments Foundation Model is trained on tens of billions of transactions across its network. Specific opt-out for model training: unknown. Rights requests go through the Privacy Center.","np":"Discounted processing on request for registered nonprofits (UK included) where at least 80% of volume is donations. Tickets, memberships and registration fees do not count.","note":"Stripe moves your payment and donor data to the US and uses transaction data to train its fraud and payments AI. Two-step login is optional, so an admin should switch on the setting that requires it for the whole team.","conf":"high","src":[["Stripe Privacy Policy","https://stripe.com/gb/privacy"],["Stripe Privacy Center","https://stripe.com/gb/legal/privacy-center"],["AI at Stripe","https://stripe.com/payments/ai"],["Fee discount for nonprofit organisations","https://support.stripe.com/questions/fee-discount-for-nonprofit-organizations?locale=en-GB"],["Export customer data without the payment details","https://support.stripe.com/questions/export-customer-data-without-the-payment-details"],["Require two-step authentication for your team","https://support.stripe.com/questions/require-two-step-authentication-for-your-team"]]},{"id":"paypal","name":"PayPal","job":"Online payments and donations","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"GB","co":"PayPal UK Ltd (UK accounts); PayPal Giving Fund UK is a separate registered charity (1110538)","par":"PayPal Holdings, Inc.","parc":"US","store":"Stored in the US and other countries by PayPal's service providers","res":"no","plans":null,"mfa":"all plans","ai":"yes","aid":"The UK privacy statement (28 October 2025) says personal data is used to improve services, including improving risk models and developing new products and features. It does not use the phrase AI training. Opt-out: unknown.","np":"Discounted charity rate on application for confirmed charities (change business type to Non-profit and submit documents). PayPal Giving Fund enrolment is free and charges no fees to charities or donors, though partner platforms may add fees.","note":"Donations through PayPal Giving Fund go to that fund first, and you only get a donor's name and email if they chose to share them. PayPal stores data in the US.","conf":"medium","src":[["PayPal Privacy Statement (UK), last updated 28 October 2025","https://www.paypalobjects.com/marketing/ua/pdf/GB/en/privacy-full-102825.pdf"],["How do I apply for the charity rate?","https://www.paypal.com/uk/cshelp/article/how-do-i-apply-for-the-charity-rate-help221"],["PayPal Giving Fund UK Enrolment Guide","https://www.paypalobjects.com/marketing/web/PPGF/UK/PPGF%20UK%20Enrolment%20Guide.pdf"],["PayPal Giving Fund FAQ","https://www.paypal.com/uk/webapps/mpp/givingfund/help-contact"],["How do I view and download statements and reports?","https://www.paypal.com/uk/cshelp/article/how-do-i-view-and-download-statements-and-reports-help145"],["What is 2-step verification and how do I turn it on or off?","https://www.paypal.com/uk/cshelp/article/what-is-2-step-verification-and-how-do-i-turn-it-on-or-off-help167"]]},{"id":"gocardless","name":"GoCardless","job":"Direct Debit collection","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"GB","co":"GoCardless Ltd","par":null,"parc":null,"store":"Main processing for European payments on servers in the EEA; some suppliers may transfer data outside the EEA","res":"yes-default","plans":"All plans","mfa":"all plans","ai":"yes","aid":"GoCardless says its Success+ retry models are trained on millions of recurring payments it has processed, and Protect+ fraud models use data from billions of transactions on its network. The merchant privacy notice (July 2026) says data is used to improve services and for automated fraud decisions. Opt-out: unknown.","np":"Charity Pricing plan: 25% off standard transaction fees for registered charities. CICs, companies limited by guarantee without share capital, custom pricing and add-on fees are excluded.","note":"GoCardless processes European payments in the EEA and you can move your Direct Debit mandates out through a bulk change. CICs do not qualify for the charity discount.","conf":"medium","src":[["Privacy Centre - Merchants","https://gocardless.com/privacy/merchants/"],["GoCardless GDPR","https://gocardless.com/privacy/en-gdpr/"],["Charity & Non Profit FAQs","https://support.gocardless.com/hc/en-gb/articles/360000367589-Charity-Non-Profit-FAQs"],["Exporting customer information","https://support.gocardless.com/hc/en-us/articles/360000136445-Exporting-customer-information"],["Bulk changing away from GoCardless","https://support.gocardless.com/hc/en-us/articles/115005800129-Bulk-changing-away-from-GoCardless"],["Enforce 2-factor authentication for all users","https://support.gocardless.com/hc/en-us/articles/17144323905564-Enforce-2-factor-authentication-for-all-users"],["How we built Success+ using our ethical machine learning programme","https://gocardless.com/blog/how-we-built-success-plus-ethical-machine-learning/"],["GoCardless launches Protect+","https://gocardless.com/blog/gocardless-launches-protect-plus/"]]},{"id":"mollie","name":"Mollie","job":"Online payments","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"","locs":[],"hq":"NL","co":"Mollie B.V. (Mollie UK Ltd for UK merchants)","par":null,"parc":null,"store":"Not stated by Mollie. Its privacy statement says some processing by third parties may happen outside the EEA. A third-party profile says Mollie commits to storing payment data in European data centres.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"The privacy statement (18 July 2026) lists developing, training, using and enhancing automated systems including AI models as a purpose. No opt-out described.","np":null,"note":"Mollie says it usually offers no discount for charities, and it does not state where it stores data. Mollie treats itself as a separate controller, not your processor, so there is no data processing agreement to sign.","conf":"medium","src":[["Mollie Privacy Statement","https://www.mollie.com/legal/privacy"],["Can I use Mollie to accept donations?","https://help.mollie.com/hc/en-gb/articles/115000632489-Can-I-use-Mollie-to-accept-donations"],["How do I export my balance report, transactions, and settlements?","https://help.mollie.com/hc/en-us/articles/115000667809-How-can-I-export-transactions-and-outpayments-"],["How do I enable multi-factor authentication (MFA)?","https://help.mollie.com/hc/en-us/articles/360018584459-How-do-I-enable-multi-factor-authentication-MFA"],["Do I have to sign a data processing agreement with Mollie?","https://help.mollie.com/hc/en-us/articles/360002761193-Do-I-have-to-sign-a-data-processing-agreement-with-Mollie"],["Mollie - EU & privacy compliance profile (EU Vetted)","https://euvetted.com/p/mollie"]]},{"id":"eventbrite","name":"Eventbrite","job":"Event ticketing","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Eventbrite, Inc.","par":"Bending Spoons S.p.A.","parc":"IT","store":"US. Eventbrite says it physically stores personal data in the United States.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"The privacy policy (15 September 2026) does not mention AI training. The organiser DPA says Eventbrite acts as an independent controller when it uses attendee data for research to improve products and give recommendations. No AI sub-processors listed.","np":"50% off the Eventbrite Pro marketing plan for verified nonprofits (via Percent). Ticketing fees are not discounted.","note":"Eventbrite stores attendee data in the US and can use it for its own product research and recommendations. Eventbrite was bought by Bending Spoons in March 2026, so review the terms again.","conf":"high","src":[["Eventbrite & EU Data Protection","https://www.eventbrite.co.uk/help/en-gb/articles/363929/eventbrite-data-protection/"],["Eventbrite Privacy Policy","https://www.eventbrite.co.uk/help/en-gb/articles/460838/eventbrite-privacy-policy/"],["Data Processing Addendum (DPA) for Organizers","https://www.eventbrite.com/help/en-us/articles/429030/data-processing-addendum-for-organizers/"],["Nonprofit pricing for Eventbrite Pro","https://www.eventbrite.co.uk/help/en-gb/articles/585157/can-my-nonprofit-or-charity-get-lower-fees-for-our-events/"],["Download an attendees report","https://www.eventbrite.com/help/en-us/articles/496608/download-an-attendees-report/"],["Logging in with multi-factor authentication","https://www.eventbrite.com/help/en-us/articles/277134/logging-in-with-multi-factor-authentication/"],["Eventbrite Subprocessors","https://www.eventbrite.co.uk/help/en-gb/articles/891292/eventbrite-subprocessors/"],["Eventbrite - Wikipedia","https://en.wikipedia.org/wiki/Eventbrite"]]},{"id":"pretix","name":"pretix (hosted)","job":"Event ticketing","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"DE","locs":["DE"],"hq":"DE","co":"pretix GmbH","par":null,"parc":null,"store":"Germany, on servers in data centres run by German companies","res":"yes-default","plans":"All hosted accounts","mfa":"all plans","ai":"no","aid":"The privacy page says pretix does not share customer data with anyone and uses event data only to run ticket sales and calculate its fees. No AI training mentioned.","np":"Non-profit pricing on request: 2.0% per paid ticket instead of 2.5% (capped at €15 or £13), and 2,500 free tickets a year before free-ticket fees apply. pretix decides eligibility case by case.","note":"pretix hosts all data in Germany and most of its code is open source, so you could run it yourself. Two-factor login is optional, so turn on the team setting that requires it.","conf":"high","src":[["Privacy at pretix","https://pretix.eu/about/en/privacy"],["Security - pretix","https://pretix.eu/about/en/security"],["Pricing - pretix (non-profit)","https://pretix.eu/about/en/pricing?nonprofit=true"],["Data exporters - pretix REST API","https://docs.pretix.eu/dev/api/resources/exporters.html"],["Two-factor authentication - pretix Documentation","https://docs.pretix.eu/guides/two-factor-authentication/"],["pretix LICENSE (GitHub)","https://github.com/pretix/pretix/blob/master/LICENSE"]]},{"id":"ticket-tailor","name":"Ticket Tailor","job":"Event ticketing","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"IE","locs":["IE","FR"],"hq":"GB","co":"Zimma Ltd (trading as Ticket Tailor)","par":null,"parc":null,"store":"EU, on AWS in Dublin (Ireland) and Paris (France)","res":"yes-default","plans":"All accounts","mfa":"all plans","ai":"unclear","aid":"The privacy policy does not mention AI or model training, and no AI sub-processors are listed. No explicit statement either way.","np":"50% off Ticket Tailor fees for registered charities, on proof of status. The help centre says other not-for-profits get 20%.","note":"Ticket Tailor stores data in Ireland and France, and registered charities can claim half-price fees. Card payments go through your own Stripe, PayPal or Square account, so check those separately.","conf":"high","src":[["GDPR - Ticket Tailor","https://www.tickettailor.com/legal/gdpr"],["Third Party Sub-Processors","https://www.tickettailor.com/legal/gdpr-third-parties"],["Privacy Policy - Ticket Tailor","https://www.tickettailor.com/legal/privacy-policy"],["I run a charity/not-for-profit organisation. Do I get a discount?","https://help.tickettailor.com/en/articles/950033-i-run-a-charity-not-for-profit-organisation-do-i-get-a-discount"],["Ticket Tailor: Pricing","https://www.tickettailor.com/en-us/pricing"],["How to export your order information","https://help.tickettailor.com/en/articles/950965-how-to-export-your-order-information"],["How to set up two-factor authentication (2FA)","https://help.tickettailor.com/en/articles/4341594-how-to-set-up-two-factor-authentication-2fa"]]},{"id":"zettle","name":"Zettle by PayPal (PayPal Point of Sale)","job":"Card readers and till","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"UNKNOWN","locs":["UNKNOWN"],"hq":"GB","co":"PayPal UK Ltd","par":"PayPal Group","parc":null,"store":"Unknown. Zettle transfers data to service providers in the US and Australia under Standard Contractual Clauses, and within the PayPal Group under Binding Corporate Rules.","res":"unclear","plans":"Plan assumed: standard UK pay-as-you-go (1.75% per card transaction, no monthly fee, reader from GBP 29 before VAT for new business users).","mfa":"all plans","ai":"unclear","aid":"Unknown.","np":null,"note":"Zettle is now branded PayPal Point of Sale, so look for either name on your account and invoices. The service is provided by PayPal UK Ltd. Two-step verification is always on: Zettle's help says 'It is not possible to disable 2-step verification on the PayPal Point of Sale account.' Export sales and product reports, and your product library as an Excel file, from my.zettle.com before you close. Ask Zettle how to get your customer list out.","conf":"low","src":[["Privacy Policy (PayPal UK Ltd)","https://www.zettle.com/gb/legal/privacy-policy"],["Pricing and fees","https://www.zettle.com/gb/pricing"],["PayPal Point of Sale Help","https://www.zettle.com/gb/help"],["About reports","https://www.zettle.com/gb/help/articles/1084803-about-reports"],["What is multi-factor authentication? (Zettle help)","https://www.zettle.com/gb/help/articles/2659461-what-is-multi-factor-authentication"],["Import and export your products (Zettle help)","https://www.zettle.com/gb/help/articles/2399581-import-and-export-your-products"]]},{"id":"sumup","name":"SumUp","job":"Card readers and payments","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"EU","locs":["EU"],"hq":"UNKNOWN","co":"SumUp Payments Limited (UK customers)","par":"SumUp Group","parc":null,"store":"SumUp says 'for our European business we store our personal data within the European Economic Area'. It may transfer data to group companies and providers outside the EEA and UK. The policy does not say whether this covers UK accounts.","res":"unclear","plans":"Plan assumed: pay-as-you-go (1.69% per in-person card payment, no monthly fee). Payments Plus is GBP 19 a month before VAT, as stated on the pricing page.","mfa":"all plans","ai":"unclear","aid":"Unknown. The privacy policy mentions developing 'machine-learning risk assessment tools' for fraud prevention and risk management. It has no statement on training on customer data for other purposes.","np":null,"note":"SumUp says it stores European data in the EEA, not the UK, so check that the wording covers your UK account. Turn on 2-step authentication for the main login: it is optional and codes go by email or SMS. Sales reports export to CSV or Excel from the dashboard. SumUp does not publish a charity rate on its charity page, so ask before assuming one.","conf":"medium","src":[["Privacy Policy (UK)","https://www.sumup.com/en-gb/privacy/"],["Pricing","https://www.sumup.com/en-gb/pricing/"],["Card readers for charities","https://www.sumup.com/en-gb/business-types/charity/"],["Activate secure login with 2-step authentication","https://help.sumup.com/en-GB/articles/3vxYu2T1X9uMXSYOspdGRr-secure-login"],["Reports","https://help.sumup.com/en-GB/articles/1K6tiRe1quFjBtGgGSs21e-reports"]]},{"id":"mobilepay","name":"MobilePay (Box, MyShop, Donations)","job":"Taking donations and payments","k":"Software","w":"Don't know","b":"UK or Europe","x":"Partial","o":false,"loc":"UNKNOWN","locs":["UNKNOWN"],"hq":"NO","co":"Vipps MobilePay AS (Danish branch)","par":null,"parc":null,"store":"Unknown. The data processing agreement allows sub-processors in third countries with safeguards, and the sub-processor list is available on request. Plan assumed: a business agreement for MyShop or Donations, and a private MobilePay profile for a Box.","res":"unclear","plans":"Box needs only a MobilePay profile: free to create and to collect the first 999 kr, then 19 kr is taken for each 1,000 kr paid in. MyShop and Donations need a business agreement. Donations cost 0.99% plus 1 kr per transaction before VAT (checked 2026-09-29).","mfa":"unclear","ai":"unclear","aid":"Unknown. Plan assumed: business agreement.","np":"Donations cost 0.79% plus 1 kr per transaction, instead of 0.99% plus 1 kr, for ISOBRO members (prices before VAT, checked 2026-09-29). There is no general non-profit price for MyShop or Box.","note":"Ask about the databehandleraftale before you use it for donor data. The published agreement covers only Loyalty and Login. For payments, the merchant terms say you and Vipps MobilePay are each independent controllers. The business portal signs in with MitID, with single sign-on if your organisation has set it up, or with an email and password for older accounts. An administrator adds each user, so name two administrators. A Box is for private use only. MobilePay says it may not be used to collect money for an organisation, so use Donations instead. Settlement and transaction reports download as PDF, Excel (XLSX) or CSV from the business portal; export of other data: unknown.","conf":"medium","src":[["Terms and Conditions for Vipps MobilePay Business Solutions","https://vippsmobilepay.com/en-NO/terms-and-conditions"],["Data Processing Agreement","https://vippsmobilepay.com/en-NO/data-processing-agreement"],["MobilePays behandling af personoplysninger","https://www.mobilepay.dk/privacy-notice"],["Priser","https://vippsmobilepay.com/da-DK/pricing"],["Modtag donationer med MobilePay","https://vippsmobilepay.com/da-DK/donationer"],["Hvor meget koster det at samle penge i en box?","https://help.vippsmobilepay.com/da-DK/articles/how-much-does-it-cost-to-use-box"],["Kan alle oprette en box?","https://help.vippsmobilepay.com/da-DK/articles/can-everyone-create-a-box"],["Log ind paa erhvervsportalen","https://help.vippsmobilepay.com/da-DK/articles/logging-in-to-businessportal"],["Saadan downloader du rapporter","https://help.vippsmobilepay.com/da-DK/articles/how-to-download-reports"],["Find the right report (Vipps MobilePay help)","https://help.vippsmobilepay.com/da-DK/articles/find-the-right-report"],["Can I use Box for my business? (Vipps MobilePay help)","https://help.vippsmobilepay.com/da-DK/articles/can-i-use-box-for-my-business"]]},{"id":"betalingsservice","name":"Betalingsservice","job":"Collecting membership fees and regular payments by direct debit","k":"Software","w":"Don't know","b":"UK or Europe","x":"Don't know","o":false,"loc":"UNKNOWN","locs":["UNKNOWN"],"hq":"DK","co":"Mastercard Payment Services Denmark A/S","par":"Mastercard","parc":"US","store":"Unknown. Mastercard's general privacy notice says data moves within the Mastercard group and may go to the USA and other countries, under binding corporate rules and similar safeguards. Plan assumed: a creditor agreement with a data supplier agreement.","res":"unclear","plans":"Unknown. Prices are in a separate price list on betalingsservice.dk. Banks also offer Betalingsservice on their own terms.","mfa":"unclear","ai":"unclear","aid":"Unknown.","np":"Unknown.","note":"No databehandleraftale is offered. Mastercard Payment Services says it is an independent controller for Betalingsservice, so 'there should be no data processing agreements for these products'. Check how your membership system or bank sends the data, as they may need their own agreement with you. You apply for, renew and sign the agreement with MitID Erhverv. You can end the agreement with one month's written notice; Mastercard Payment Services can end it with two months' notice. An ended agreement cannot be reopened, and ended payment agreements cannot be restored. Ask what you can export and how you would move members to another way of collecting. Export terms and two-step login: unknown.","conf":"low","src":[["GDPR (Mastercard Payment Services)","https://www.mastercardpaymentservices.com/common/gdpr/"],["Betalingsservice","https://betalingsservice.mastercard.com/"],["Generelle regler for kreditorer i Betalingsservice","https://www.betalingsservice.dk/media/r4bh0equ/bs_regler_kr_dk.pdf"],["Privacy notice, Betalingsservice (March 2026)","https://www.mastercardpaymentservices.com/media/hk4cps0a/privacy_notice-betalingsservice_march2026_final.pdf"],["Terms of use","https://www.mastercardpaymentservices.com/common/terms-of-use-dk/"],["Privacy Notice (Mastercard Payment Services)","https://www.mastercardpaymentservices.com/common/privacy-notice/"],["Beskyttelse af personlige oplysninger, Betalingsservice (March 2026)","https://www.mastercardpaymentservices.com/media/3ovjx4qk/beskyttelse_af_personlige_oplysninger-betalingsservice.pdf"]]}]},{"g":"Websites and forms","items":[{"id":"wordpress-com","name":"WordPress.com","job":"Website hosting","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US","EU"],"hq":"US","co":"Automattic Inc.","par":null,"parc":null,"store":"US and EU. WordPress.com stores personal data on servers in both the US and the EU and cannot restrict a site to one location. Self-hosted WordPress is different: data lives wherever your web host puts it.","res":"no","plans":"Business plan sites can pick EU West as the primary data centre when hosting features are first activated, but data is still not restricted to the EU.","mfa":"all plans","ai":"yes","aid":"Automattic licenses public site content to third parties, including AI companies, unless you tick 'Prevent third-party sharing' under Settings, Reading. This applies to public content. Assumed plan: Personal or Premium.","np":null,"note":"WordPress.com shares public site content with AI companies unless you tick 'Prevent third-party sharing' in Settings, Reading. If your site is self-hosted WordPress, ask your web host where the server is.","conf":"high","src":[["Your WordPress.com site and the GDPR","https://wordpress.com/support/your-site-and-the-gdpr/"],["Choose your site's primary data center","https://wordpress.com/support/choose-your-sites-primary-data-center/"],["Make your website public","https://wordpress.com/support/privacy-settings/make-your-website-public/"],["Enable two-step authentication","https://wordpress.com/support/security/two-step-authentication/"],["Export your website's content","https://wordpress.com/support/export/"]]},{"id":"squarespace","name":"Squarespace","job":"Website and online shop","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Squarespace Ireland Limited","par":"Squarespace, Inc.","parc":"US","store":"US. Squarespace's privacy policy refers to 'our servers in the US', and its data processing addendum lets it transfer your data to other countries, in particular the US. Customers outside the US contract with Squarespace Ireland Limited.","res":"unclear","plans":"Plan assumed: any paid plan (Basic, Core, Plus or Advanced). Squarespace does not describe a storage choice on any plan.","mfa":"all plans","ai":"unclear","aid":"Unknown. Squarespace's terms and privacy policy do not say whether customer content is used to train AI models. The terms let it use your content to provide and improve the services. Its help page says you can ask known AI crawlers to exclude your site; this is off by default and 'doesn't retroactively remove content previously scraped'.","np":"Enter NONPROFIT at checkout for 10% off your first payment (Squarespace help article, Building a nonprofit site).","note":"Your site and contact records are held in the US. Squarespace says it exports only some content: one blog with its posts, layout pages and text and image blocks. Store pages, product blocks, video and audio blocks, styling and custom CSS do not export. Check what you would need to rebuild before you choose it. Two-factor sign-in (passkey, authenticator app or text message) is switched on by each person for their own account, so check every contributor has done it.","conf":"high","src":[["Squarespace privacy policy","https://www.squarespace.com/privacy"],["Squarespace Data Processing Addendum","https://www.squarespace.com/dpa"],["Squarespace Terms of Service","https://www.squarespace.com/terms-of-service"],["Exporting your site (Squarespace help)","https://support.squarespace.com/hc/en-us/articles/206566687-Exporting-your-site"],["Protect your account with two-factor authentication (Squarespace help)","https://support.squarespace.com/hc/en-us/articles/360000044827-Protect-your-account-with-two-factor-authentication"],["Building a nonprofit site (Squarespace help)","https://support.squarespace.com/hc/en-us/articles/115015429248-Building-a-nonprofit-site"],["Request that AI models exclude your site (Squarespace help)","https://support.squarespace.com/hc/en-us/articles/360022347072-Request-that-AI-models-exclude-your-site"]]},{"id":"wix","name":"Wix","job":"Website builder","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US","IE"],"hq":"OTHER","co":"Wix.com Ltd. (Israel) and its affiliated companies","par":null,"parc":null,"store":"Wix says it stores information in data centres in the United States and Ireland. It does not say which one holds your site, and it also uses group companies and processors worldwide.","res":"unclear","plans":"Plan assumed: any Wix Premium plan. Wix does not say the data location differs by plan.","mfa":"unclear","ai":"yes","aid":"Wix's Generative AI Policy lists 'User-generated content (such as images and page layouts)' as a data source for its AI models, under a 'License given to Wix in the Terms of Use'. The policy describes no opt-out. Plan assumed: any Wix Premium plan.","np":"70% off a 2-year Wix Premium plan for one website, plus a free 1-year domain voucher, for TechSoup member charities in 37 listed countries, including the United Kingdom and Ireland. Denmark is not listed; Wix says to contact it from an unlisted country. One coupon every 2 years. It renews at the standard rate unless you cancel. Not for Wix Studio plans.","note":"Wix keeps data in the US and Ireland. Whether you can choose between them: unknown. Wix says it uses content you create on its platform, such as images and page layouts, to develop its AI models, and describes no opt-out, so read its Generative AI Policy before you upload personal data. Wix does not offer a full-site export, so export your contacts, products, orders and bookings as CSV files before you cancel. Wix says you can turn on 2-step verification for your account, but does not say which plans include it, so check your own account settings. The discount renews at the standard rate after two years unless you cancel.","conf":"medium","src":[["Wix Trust Center FAQ","https://www.wix.com/trust-center/faq"],["Wix Privacy Policy","https://www.wix.com/about/privacy"],["Wix Terms of Use","https://www.wix.com/about/terms-of-use"],["Premium plan discount for charities or non-profit organisations","https://support.wix.com/en/article/premium-plan-discount-for-charities-or-non-profit-organizations"],["Exporting your contacts","https://support.wix.com/en/article/exporting-your-contacts"],["Using 2-step verification for your Wix account","https://support.wix.com/en/article/using-2-step-verification-for-your-wix-account"],["Wix's Generative AI Policy","https://support.wix.com/en/article/wixs-generative-ai-policy"]]},{"id":"shopify","name":"Shopify","job":"Online shop and payments","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"UNKNOWN","locs":["UNKNOWN"],"hq":"OTHER","co":"Shopify International Limited (Ireland)","par":"Shopify Inc.","parc":"OTHER","store":"Shopify does not say which country holds your shop data. Its data processing addendum says customer personal data may be transferred and processed in any country where Shopify, its affiliates or service providers are located, including Singapore and Canada.","res":"unclear","plans":"Plan assumed: Basic, Grow or Advanced. Shopify's help says requiring staff to sign in with a secure method is available only on Shopify Plus.","mfa":"unclear","ai":"unclear","aid":"AI model training: unknown. Shopify's terms say Shopify Network Intelligence uses your customer data alongside data from other merchants and from Shopify for Enhanced Services, and you can turn it off in Settings, Customer Privacy. Plan assumed: Basic, Grow or Advanced.","np":null,"note":"Shopify does not name a country for your shop data, so ask where orders and customer records are kept. You can export products, customers and orders as CSV files from the admin, but check whether your theme, pages and app data come with them. Each person sets up two-step sign-in on their own account, and only Shopify Plus can require it for everyone, so check every staff account has it on. Check whether Shopify Network Intelligence is off if you want it off. Your contract is with Shopify International Limited, in Ireland.","conf":"medium","src":[["Shopify Data Processing Addendum","https://www.shopify.com/legal/dpa"],["Shopify Terms of Service","https://www.shopify.com/legal/terms"],["Shopify pricing (UK)","https://www.shopify.com/uk/pricing"],["Requiring a secure sign-in method (Shopify Help Center)","https://help.shopify.com/en/manual/your-account/users/security/advanced-security-features/requiring-secure-sign-in"],["Secure sign-in (Shopify Help Center)","https://help.shopify.com/en/manual/your-account/logging-in/secure-sign-in"],["Import and export customers (Shopify Help Center)","https://help.shopify.com/en/manual/customers/import-export-customers"],["Exporting orders (Shopify Help Center)","https://help.shopify.com/en/manual/fulfillment/managing-orders/exporting-orders"]]},{"id":"google-analytics-4","name":"Google Analytics 4","job":"Website analytics","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Google LLC","par":"Alphabet Inc.","parc":"US","store":"Global Google data centres, with no residency option. Traffic from UK and EU devices is collected on UK or EU servers and IP addresses are discarded, but data is then forwarded to Analytics servers for processing.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"GA has data sharing settings, including 'Google products & services', which lets Google use your data to improve Google products, and 'Modeling contributions & business insights'. These are chosen at sign-up and can be changed under Admin, Account settings. Google does not state clearly on the help page which are on by default. Assumed plan: free standard GA4 property.","np":null,"note":"Google Analytics sends data outside the UK and EU and keeps detailed data for 14 months at most. Check the data sharing settings in Admin and switch off any you do not need.","conf":"medium","src":[["[GA4] EU-focused data and privacy","https://support.google.com/analytics/answer/12017362?hl=en"],["Safeguarding your data","https://support.google.com/analytics/answer/6004245"],["Data sharing settings","https://support.google.com/analytics/answer/1011397"],["[GA4] Data retention","https://support.google.com/analytics/answer/7667196"],["[GA4] Set up BigQuery Export","https://support.google.com/analytics/answer/9823238"],["Turn on 2-Step Verification","https://support.google.com/accounts/answer/185839?hl=en"]]},{"id":"plausible-analytics","name":"Plausible Analytics","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"DE","locs":["DE"],"hq":"EE","co":"Plausible Insights OÜ","par":null,"parc":null,"store":"Germany. Visitor data is stored on Hetzner servers in Falkenstein, Germany, on EU-owned infrastructure.","res":"yes-default","plans":"All cloud plans","mfa":"all plans","ai":"unclear","aid":"Statement on AI training: unknown. Plausible's DPA says it processes visitor data only on the customer's documented instructions, and its data policy says data is not used for advertising, profiling or monetisation. Assumed plan: Starter or Growth cloud plan.","np":"15% off Business plans on annual billing, plus 2 free months, for nonprofits. Apply by contacting Plausible for a code.","note":"Plausible keeps your website statistics in Germany with an EU company. You can only export summary figures on normal plans, not raw visit logs.","conf":"high","src":[["Plausible Privacy Policy","https://plausible.io/privacy"],["Plausible Data Policy","https://plausible.io/data-policy"],["Security Practices","https://plausible.io/security"],["Plausible Data Processing Agreement","https://plausible.io/dpa"],["Export stats","https://plausible.io/docs/export-stats"],["Discount for nonprofits and educational institutions","https://plausible.io/docs/nonprofit-and-education-pricing"],["plausible/analytics README","https://github.com/plausible/analytics"]]},{"id":"umami-cloud","name":"Umami Cloud","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"US","co":"Umami Software, Inc.","par":null,"parc":null,"store":"You pick US or European Union as the data region when you set up the account. It cannot be changed afterwards.","res":"yes-default","plans":"All cloud plans, if EU is selected at account setup","mfa":"unclear","ai":"unclear","aid":"The privacy policy says Umami does not sell or share personal information, but it says nothing about AI training. Assumed plan: Hobby (free) or Pro.","np":null,"note":"Choose European Union when you set up Umami Cloud, because the data region cannot be changed later. The company is based in the US.","conf":"medium","src":[["Umami Pricing (FAQ)","https://umami.is/pricing"],["Umami Cloud: Sign up","https://umami.is/docs/cloud/sign-up"],["Umami Cloud: Export data","https://umami.is/docs/cloud/export-data"],["Umami Privacy Policy","https://umami.is/privacy"],["umami-software/umami licence","https://github.com/umami-software/umami/blob/master/LICENSE"]]},{"id":"matomo-cloud","name":"Matomo Cloud","job":"Website analytics","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"DE","locs":["DE","IE"],"hq":"OTHER","co":"InnoCraft Ltd","par":null,"parc":null,"store":"Germany. Matomo Cloud is hosted on AWS in Frankfurt, with backups in Dublin.","res":"yes-default","plans":"All Matomo Cloud plans","mfa":"all plans","ai":"unclear","aid":"InnoCraft acts as processor under the Matomo Cloud DPA. AI training on customer analytics data: unknown. Matomo's website privacy policy says its AI providers receive only aggregated reports and may not train general-purpose models. Assumed plan: Business or entry Cloud plan.","np":"Eligible non-profits may receive a discount on request.","note":"Matomo Cloud keeps your analytics in Germany. The company is in New Zealand, which the EU and UK treat as having adequate data protection.","conf":"high","src":[["Matomo Pricing (FAQ)","https://matomo.org/pricing/"],["Matomo Cloud Data Processing Agreement","https://matomo.org/matomo-cloud-dpa/"],["Matomo Cloud Privacy Policy","https://matomo.org/matomo-cloud-privacy-policy/"],["What is Two-Factor Authentication?","https://matomo.org/faq/general/faq_27245/"],["Matomo Privacy Policy","https://matomo.org/privacy-policy/"],["matomo-org/matomo LICENSE","https://github.com/matomo-org/matomo/blob/5.x-dev/LICENSE"]]},{"id":"surveymonkey","name":"SurveyMonkey","job":"Surveys and forms","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"SurveyMonkey Inc. (EU entity: SurveyMonkey Europe UC, Ireland)","par":null,"parc":null,"store":"US by default on AWS. The EU data centre is only available to Enterprise customers.","res":"yes-some-plans","plans":"Enterprise only (per the International Data Center Overview updated 15 April 2025)","mfa":"some plans","ai":"yes","aid":"The privacy notice says SurveyMonkey uses de-identified response data to train its models, and sentiment analysis and other machine learning features are switched on for all accounts and cannot be turned off. No opt-out from de-identified training is described. Assumed plan: Team Advantage or individual Advantage.","np":"Discounts for eligible nonprofits upgrading from a free plan, at SurveyMonkey's discretion and varying by country.","note":"On ordinary plans SurveyMonkey stores your surveys in the US, as the EU data centre is Enterprise only. Free accounts cannot export responses or use two-factor sign-in.","conf":"high","src":[["International Data Center Overview","https://www.surveymonkey.com/mp/legal/international-data-center-overview/"],["SurveyMonkey Privacy Notice","https://www.surveymonkey.com/mp/legal/privacy/"],["SurveyMonkey AI Principles","https://www.surveymonkey.com/product/features/ai-principles/"],["Two-factor Authentication (2FA)","https://help.surveymonkey.com/en/surveymonkey/account/two-factor-authentication/"],["Exporting Survey Results","https://help.surveymonkey.com/en/surveymonkey/analyze/exports/"],["SurveyMonkey for nonprofits","https://www.surveymonkey.com/learn/nonprofit/"]]},{"id":"typeform","name":"Typeform","job":"Surveys and forms","k":"Software","w":"Elsewhere","b":"UK or Europe","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"ES","co":"TYPEFORM, S.L.","par":null,"parc":null,"store":"US by default. Typeform's main servers are on AWS in Virginia, USA. EU data hosting is only on Enterprise or Growth Custom plans.","res":"yes-some-plans","plans":"Enterprise and Growth Custom","mfa":"all plans","ai":"no","aid":"Typeform's AI FAQ says none of its customers' data is used to train any model. AI-powered insights can be switched off in Admin settings. Assumed plan: Basic or Plus.","np":"NGO discount of 25% forever on monthly plans or 40% forever on yearly plans, by application.","note":"Typeform is a Spanish company but stores your forms in the US unless you are on an Enterprise or Growth Custom plan.","conf":"high","src":[["Security at Typeform","https://help.typeform.com/hc/en-us/articles/360029259552-Security-at-Typeform"],["Integrations available on the EU Data Center","https://help.typeform.com/hc/en-us/articles/52254048333588-Integrations-available-on-the-EU-Data-Center"],["AI with Typeform FAQ","https://help.typeform.com/hc/en-us/articles/33777155298708-AI-with-Typeform-FAQ"],["Export your responses","https://help.typeform.com/hc/en-us/articles/360029253572-Export-your-responses"],["Data portability","https://help.typeform.com/hc/en-us/articles/360029616371-Data-portability"],["Non-profit, NGO, and student discounts at Typeform","https://help.typeform.com/hc/en-us/articles/360039728951-Non-profit-NGO-and-student-discounts-at-Typeform"],["Typeform Privacy Policy","https://www.typeform.com/legal/privacy-policy"]]},{"id":"jotform","name":"Jotform","job":"Online forms","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Jotform Inc.","par":null,"parc":null,"store":"US by default. You can switch to EU storage in account settings (or use eu.jotform.com); form data then moves to Google Cloud servers in Frankfurt, Germany.","res":"yes-on-request","plans":"Offered as an account setting; Jotform does not say it is limited to any plan.","mfa":"all plans","ai":"yes","aid":"Jotform's AI policy says personal data is never used to train its AI, but 'data you include in the forms you create, such as in form fields, may be used to train our AI'. No opt-out is described. Assumed plan: Bronze or Silver.","np":"50% off all annual plans for nonprofit organisations.","note":"Jotform stores forms in the US unless you switch on EU storage in your account settings, so check the Data tab. Its AI policy allows form content to be used for AI training.","conf":"medium","src":[["Jotform Privacy Policy","https://www.jotform.com/privacy/"],["Jotform Security","https://www.jotform.com/security/"],["Jotform EU Safe Forms","https://www.jotform.com/eu-safe-forms/"],["Jotform AI Policy","https://www.jotform.com/ai-policy/"],["Jotform for Nonprofits","https://www.jotform.com/nonprofit/"]]},{"id":"tally","name":"Tally","job":"Online forms","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"BE","co":"Tally BV","par":null,"parc":null,"store":"EU. Tally says it is 'Made and hosted in the EU' and that all form data is encrypted and stored in Europe. Exact country: unknown.","res":"yes-default","plans":"All plans. Two-factor sign-in has no stated plan limit.","mfa":"all plans","ai":"unclear","aid":"Unknown. Tally has no explicit statement on training AI models. Its DPA says it processes personal data only on the customer's documented instructions and not for other purposes. The privacy notice separately says Tally may use data you provide to improve the tool. Assumed plan: Free or Pro.","np":"30% off Tally Pro forever for new Pro customers that are non-profits.","note":"Tally is a Belgian company and stores form data in the EU. Tally offers two-factor sign-in with an authenticator app, which each person turns on in their own account settings, so check every user has done it. You can download form responses as CSV from the Submissions tab.","conf":"medium","src":[["GDPR (Tally Help)","https://tally.so/help/gdpr"],["Privacy Notice - Tally tool","https://tally.so/help/privacy-policy"],["Tally Data Processing Agreement","https://tally.so/help/data-processing-agreement"],["Tally FAQ","https://tally.so/help/faq"],["Tally for non-profit","https://tally.so/help/tally-for-non-profit"],["Account settings (Tally Help)","https://tally.so/help/account-settings"]]},{"id":"limesurvey-cloud","name":"LimeSurvey Cloud","job":"Surveys","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":true,"loc":"DE","locs":["DE","FI","GB"],"hq":"DE","co":"LimeSurvey GmbH","par":null,"parc":null,"store":"You choose the server country when creating the instance: Germany, Finland, United Kingdom, USA, Canada or Australia. Data is then stored only in that country.","res":"yes-default","plans":"All Cloud plans, by choosing Germany, Finland or UK at setup","mfa":"all plans","ai":"unclear","aid":"Unknown. LimeSurvey's privacy notice and product pages do not mention AI training. Assumed plan: Basic or Expert Cloud plan.","np":"30% discount for charitable organisations on proof of charity status.","note":"When you create your LimeSurvey Cloud site, choose the UK, Germany or Finland as the server location. Two-factor sign-in is a built-in plugin you need to switch on.","conf":"medium","src":[["LimeSurvey Pricing (FAQ)","https://www.limesurvey.org/pricing"],["LimeSurvey Privacy Notice","https://www.limesurvey.org/privacy-notice"],["TwoFactorAdminLogin (LimeSurvey Manual)","https://www.limesurvey.org/manual/TwoFactorAdminLogin"],["Exporting results (LimeSurvey Manual)","https://www.limesurvey.org/manual/Exporting_results"],["LimeSurvey README","https://github.com/LimeSurvey/LimeSurvey"]]}]},{"g":"Money","items":[{"id":"xero","name":"Xero","job":"Accounting and bookkeeping","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US","NZ"],"hq":"OTHER","co":"Xero Limited","par":null,"parc":null,"store":"US by default. Xero says it hosts customer data with AWS on servers in the US, and some EU customer data is processed in New Zealand.","res":"no","plans":null,"mfa":"all plans","ai":"unclear","aid":"Xero says its JAX assistant does not use customer data to train the LLMs it uses, and its AWS, Azure and GCP model providers do not retain it. Separately, the UK privacy notice says Xero uses personal data to improve services and develop new products 'using AI/ML' and offers no specific opt-out. Assumed plan: Standard or Premium business plan.","np":"25% off business pricing plans for registered not-for-profits, applied after Xero verifies charity status (claim within 31 days of subscribing).","note":"Xero stores your accounts in the US, not the UK. Export your reports, CSV lists and attachments before you ever cancel, as there is no one-click full backup.","conf":"high","src":[["Xero and GDPR: Protecting Your Personal Data","https://www.xero.com/uk/data/xero-and-gdpr/"],["Xero Privacy Notice (UK)","https://www.xero.com/uk/legal/privacy/"],["Multi-factor authentication FAQs","https://www.xero.com/us/security/multi-factor-authentication/faq/"],["Just Ask Xero (JAX)","https://www.xero.com/uk/ai-in-accounting/jax/"],["Accounting software for non-profit organisations","https://www.xero.com/uk/small-businesses/non-profit/"],["Export accounting data out of Xero","https://central.xero.com/0/article/Export-general-ledger-data-out-of-Xero"],["Leaving Xero? Everything You Need to Know About Your Data (Boxkite)","https://www.getboxkite.com/blog/leaving-xero-everything-you-need-to-know-about-your-data"]]},{"id":"quickbooks-online","name":"QuickBooks Online","job":"Accounting and bookkeeping","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":[],"hq":"US","co":"Intuit Limited (UK) / Intuit Inc.","par":"Intuit Inc.","parc":"US","store":"Not clearly stated. A UK help article says data is kept on AWS 'in your home country to satisfy data residency laws', but Intuit's UK GDPR page reserves the right to store and process data in the US and other countries.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"Intuit's global privacy statement says it may use personal information to improve and develop products 'by training our artificial intelligence models and other machine learning models', and creates anonymised aggregate statistics. No specific opt-out is offered beyond general UK/EU data rights such as objecting to processing. Assumed plan: Simple Start or Essentials.","np":null,"note":"Intuit does not clearly say whether UK accounts are stored in the UK, and it trains its AI models on customer data. Ask Intuit in writing where your data is held if that matters to your trustees.","conf":"medium","src":[["Privacy and security in QuickBooks (UK help)","https://quickbooks.intuit.com/learn-support/en-uk/help-article/banking/privacy-security-quickbooks/L7q2gUqfM_GB_en_GB"],["QuickBooks GDPR Centre","https://quickbooks.intuit.com/uk/gdpr/"],["Intuit Global Privacy Statement","https://www.intuit.com/privacy/statement/"],["Secure your Intuit Account with extra verification","https://quickbooks.intuit.com/learn-support/en-us/help-article/security-risk/verify-account-multi-factor-authentication/L2Xp0GNiT_US_en_US"],["Export your QuickBooks Online data","https://quickbooks.intuit.com/learn-support/en-us/help-article/list-management/export-reports-lists-data-quickbooks-online/L1xleDrLp_US_en_US"],["Accounting Software for Nonprofits (UK)","https://quickbooks.intuit.com/uk/industry/nonprofit-accounting/"]]},{"id":"sage-accounting","name":"Sage Accounting","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"IE","locs":["IE"],"hq":"GB","co":"The Sage Group plc","par":null,"parc":null,"store":"Ireland. Sage lists AWS in Ireland as the data hosting location for Sage Business Cloud Accounting.","res":"yes-default","plans":"All Sage Accounting plans","mfa":"all plans","ai":"yes","aid":"Sage's AI and data ethics principles say it analyses customer product data together with other customers' data 'to develop and train AI models', and that it does not offer a choice on use of anonymised data. Identifiable data is not shared with third parties without permission. Assumed plan: Sage Accounting Standard or Plus.","np":"Sage says registered charities, trusts and non-profits can save up to 50% through Sage Foundation. Check the offer is still live before relying on it.","note":"Sage keeps your accounts in Ireland, inside the EU. Sage uses anonymised customer data to train its AI and there is no opt-out for that.","conf":"medium","src":[["Customer Due Diligence - Privacy at Sage","https://www.sage.com/en-gb/trust-security/privacy/customer-due-diligence/"],["Sage Two-Factor Authentication (2FA)","https://www.sage.com/en-gb/trust-security/2fa/"],["Data ethics and principles at Sage","https://www.sage.com/en-us/trust-security/ai-ethics/"],["Accounting Software for Charities & Non-Profits","https://www.sage.com/en-gb/sage-business-cloud/sage-accounting/industry/non-profit/"],["Export your bank transactions (Sage KB)","https://help.accounting.sage.com/en-gb/accounting/reporting/export-data--accounting.html"]]},{"id":"e-conomic","name":"e-conomic","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"EU","locs":["EU","IE","NL"],"hq":"DK","co":"Visma e-conomic A/S","par":"Visma","parc":"NO","store":"EU. e-conomic says your accounting data is hosted in the EU. Its sub-processor list names Google Cloud (Ireland) for the application and database servers and Microsoft Azure (Netherlands and Ireland) for the database backup. The list also names suppliers outside the EU, such as Twilio SendGrid (USA) for sending email, so read the current list. Assumed plan: any e-conomic package.","res":"yes-default","plans":"Packages are Basis, Plus, Smart and Komplet, from 249 to 649 kr a month before VAT (checked 2026-09-29). e-conomic does not say the hosting differs by package.","mfa":"all plans","ai":"unclear","aid":"e-conomic's subscription terms let it use your application data 'to maintain, offer, price and develop the Application'. After the agreement ends it may use the data in anonymised form. The terms do not mention training AI models. Assumed plan: any e-conomic package.","np":"Unknown.","note":"A databehandleraftale (data processing agreement) is offered on e-conomic's own site, and you can download it from the help centre. Export your data before you cancel. The terms say e-conomic may delete it after the agreement ends, and export is via CSV files. An archive licence keeps data for 5 years if you buy one. Two-factor sign-in (2FA) is required for every user.","conf":"medium","src":[["Databehandleraftale (data processing agreement)","https://www.e-conomic.dk/sikkerhed/dpa"],["Sikkerhed i e-conomic","https://www.e-conomic.dk/sikkerhed"],["Abonnementsvilkaar for e-conomic","https://www.e-conomic.dk/abonnementsvilkaar-e-conomic"],["Priser paa e-conomic","https://www.e-conomic.dk/priser"],["Download din databehandleraftale","https://www.e-conomic.dk/support/artikler/download-din-databehandleraftale"],["Eksport af data","https://www.e-conomic.dk/support/artikler/eksport-af-data"],["Eksporter og opbevar data foer opsigelse","https://www.e-conomic.dk/support/artikler/eksporter-og-opbevar-selv-din-data"],["Totrinsbekraeftelse (2FA)","https://www.e-conomic.dk/support/artikler/om-totrinsbekraeftelse-2fa"],["Opsaet paakraevet 2FA ved login (e-conomic help)","https://www.e-conomic.dk/support/artikler/totrinsbekraeftelse-ved-login-i-e-conomic"]]},{"id":"freeagent","name":"FreeAgent","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"IE","locs":["IE","GB"],"hq":"GB","co":"FreeAgent Central Limited","par":"NatWest Group","parc":"GB","store":"FreeAgent says it stores customer information 'in data centres located in Ireland across multiple availability zones'. Its Trust Centre says the UK, so check which applies to you. Its subprocessor list also names AWS, Google Cloud and DigitalOcean with locations in the US, UK and EU.","res":"yes-default","plans":"Plan assumed: any FreeAgent plan (sole trader, partnership, limited company or landlord). No plan difference is stated.","mfa":"all plans","ai":"unclear","aid":"Unknown. FreeAgent's Trust Centre says it has internal policies and controls for AI, and no AI or LLM provider appears in its subprocessor list. Its privacy notice does not mention AI. There is no statement on training on customer data.","np":"50% off FreeAgent subscription costs for registered charities. Not applied automatically: contact FreeAgent support with your charity number. Not-for-profits, CICs and social enterprises are considered case by case. It does not apply to purchased add-ons (FreeAgent help article, Choosing the appropriate business type for a charity).","note":"FreeAgent stores your accounts in Ireland (its Trust Centre says UK). 2-step verification is optional and uses an authenticator app, so switch it on for every user. Use Export All Data to take a full copy with attachments before you ever cancel. FreeAgent offers registered charities 50% off, but you have to ask support for it. FreeAgent is owned by NatWest Group and is free with some NatWest business accounts, so check what happens to your plan if you close that account.","conf":"medium","src":[["How FreeAgent keeps your data secure","https://www.freeagent.com/features/security/"],["FreeAgent and GDPR compliance","https://www.freeagent.com/company/gdpr/"],["FreeAgent subprocessors","https://www.freeagent.com/en/privacy/freeagent-subprocessors/"],["FreeAgent Trust Centre","https://trustcentre.freeagent.com/"],["Enable and use 2-Step Verification in your FreeAgent account","https://support.freeagent.com/hc/en-gb/articles/115001223424-2-Step-Verification"],["Pricing","https://www.freeagent.com/pricing/"],["About us","https://www.freeagent.com/company/"],["Choosing the appropriate business type for a charity (FreeAgent help)","https://support.freeagent.com/hc/en-us/articles/115001218410-Choosing-the-appropriate-business-type-for-a-charity"]]},{"id":"dinero","name":"Dinero","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"NL","locs":["NL","IE"],"hq":"DK","co":"Visma Dinero ApS","par":"Visma","parc":"NO","store":"Netherlands, with a copy in Ireland. Dinero says it is hosted in the cloud with Google and Microsoft Azure, with files and data physically on servers in the Netherlands, and uploaded files also mirrored on servers in Ireland. Its sub-processor list also names some US-based suppliers (for example Mailchimp and Datadog) and says it uses EU standard contractual clauses where a supplier is outside the EU. Assumed plan: any Dinero plan.","res":"yes-default","plans":"Starter (free, up to 100,000 kr yearly revenue), Starter+, Pro and Total, from 245 to 545 kr a month (checked 2026-09-29). Whether those prices include VAT: unknown. Dinero's pages do not say the hosting differs by plan.","mfa":"unclear","ai":"unclear","aid":"Dinero's terms let it use your application data 'to maintain, offer, price and develop the Application', and after the user relationship ends only in anonymised form. The terms do not mention training AI models. Dinero's sub-processor list names Microsoft Azure as host of 'databases and AI models' and Visma's SmartScan for reading invoice data. Assumed plan: any Dinero plan.","np":"No non-profit discount is listed. Dinero says Dinero Starter (free up to 100,000 kr yearly revenue) can be used by associations, and it has a version set up for associations.","note":"A databehandleraftale is offered. Dinero says it takes effect when you register as a customer, and that continued use after an update counts as acceptance. Two-factor login can be switched on, but Dinero does not say who must use it or on which plan, so check each user has it. Export: postings, account statements and reports download as CSV or PDF, a SAF-T file is available, and contacts and products export as CSV. The paid backup file (495 kr before VAT) holds reports, sales invoices and credit notes, postings and all uploaded bilag that have been posted, as PDF and CSV, one financial year at a time. Dinero says it keeps accounting data for five years after you cancel.","conf":"high","src":[["Sikkerhed og drift","https://dinero.dk/sikkerhed/drift/"],["Databehandleraftale","https://dinero.dk/sikkerhed/databehandleraftale-databehandleren/"],["Underdatabehandlere","https://dinero.dk/sikkerhed/underdatabehandlere/"],["Betingelser ved brug af Dinero Regnskab","https://dinero.dk/sikkerhed/dinero-betingelser/"],["Priser","https://dinero.dk/priser/"],["To-faktor-login","https://dinero.dk/support/to-faktor-login/"],["Saadan faar du en backup-fil af dit regnskab","https://dinero.dk/support/saadan-faar-du-en-backup-fil-af-dit-regnskab/"],["Manuel backup af dit regnskab","https://dinero.dk/support/manuel-backup-af-dit-regnskab/"],["Eksport af posteringer og rapporter","https://dinero.dk/funktioner/eksport-posteringer-rapporter/"],["Import/eksport af kontakter og produkter","https://dinero.dk/funktioner/import-kontakter-produkter/"],["Dinero for foreninger","https://dinero.dk/hvem-er-dinero-for/foreninger/"]]},{"id":"billy","name":"Billy (now Shine Regnskab)","job":"Accounting and bookkeeping","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"EU","locs":["EU","LU","IE"],"hq":"DK","co":"Shine Denmark ApS","par":"Shine","parc":null,"store":"EU. Shine's privacy policy says your data is kept on servers with Google Cloud and Amazon Web Services inside the EU, but some data is also passed outside the EU, including to the USA. Its data processing agreement lists Amazon (Luxembourg) and Google (Ireland) and some US suppliers such as Stripe, Intercom and Datadog. Assumed plan: any Billy or Shine Regnskab plan.","res":"yes-default","plans":"Free (3 invoices and 10 expense receipts a month), Basic 160 kr, Plus 295 kr and Complete 595 kr a month before VAT on annual payment; Basic 225 kr and Plus 345 kr on monthly payment (checked 8 October 2026). Complete has a 12-month minimum term. Billy's pages do not say the hosting differs by plan.","mfa":"unclear","ai":"no","aid":"Shine's privacy policy says your data is not used 'for developing, training or improving AI technologies, except when strictly necessary to deliver our services'. This is the Shine policy, not a Billy-only one. Its terms let Shine use ideas or suggestions you send it, or post in a public area, without compensation. Assumed plan: any plan.","np":"No non-profit discount is listed on Billy's pricing pages or in its article on accounting for non-profits.","note":"Billy is now run under the Shine name, and billy.dk pages for the data processing agreement and terms send you to Shine's pages. A databehandleraftale is offered and counts as signed when you accept the terms. Export before you cancel: the older Billy terms say you must do the export yourself before the subscription ends. Billy's backup is a zip file with a folder for each transaction, converted to PDF with its attachments. Lists such as the posting journal, contacts, products and chart of accounts export separately (CSV, Excel or PDF), so export those too. Two-factor login: unknown, so ask Shine whether it is available on your plan. The contracting company for Denmark is Shine Denmark ApS. The privacy policy names Ageras A/S as data controller, and the terms define the Shine Group as Ageras A/S and its subsidiaries.","conf":"medium","src":[["Databehandleraftale (Shine)","https://shine.co/dk/legal/dpa"],["Servicevilkaar (Shine)","https://shine.co/dk/legal/terms"],["Privatlivspolitik (Shine)","https://shine.co/dk/legal/privacy"],["Generelle betingelser, Billy ApS (2022)","https://www.billy.dk/generelle-betingelser-2022-03-30/"],["Billy's priser","https://www.billy.dk/pris/"],["Shine Regnskab","https://shine.co/dk/regnskab"],["Backup af dit regnskab","https://www.billy.dk/support/article/backup-i-billy/"],["Eksport af kassekladde (Billy)","https://www.billy.dk/support/article/eksport-af-kassekladde/"],["Regnskabsprogram til non-profits (Billy)","https://www.billy.dk/blog/regnskabsprogram-til-sma-non-profits/"]]}]},{"g":"Security and task management","items":[{"id":"1password","name":"1Password","job":"Password manager","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"EU","locs":["EU"],"hq":"OTHER","co":"AgileBits Inc. (1Password)","par":null,"parc":null,"store":"Depends on the sign-up site: accounts made on 1Password.eu are hosted in the EU, 1Password.com in the US. Data is never moved automatically between regions.","res":"yes-on-request","plans":"All plans; choose 1Password.eu when creating the account","mfa":"all plans","ai":"not-applicable","aid":"Vault items are end-to-end encrypted and 1Password staff cannot read them. The privacy notice does not describe using customer data to train AI.","np":"Discounts for eligible nonprofits through the sales team; no published rate.","note":"Make sure your account address ends in 1Password.eu if you want EU hosting, because an account made on 1Password.com is in the US and cannot be moved without starting again.","conf":"high","src":[["1Password in your region","https://support.1password.com/regions/"],["1Password Privacy Notice","https://1password.com/legal/privacy"],["Export your data from 1Password","https://support.1password.com/export/"],["Use two-factor authentication for your 1Password account","https://support.1password.com/two-factor-authentication/"],["About the 1Password security model","https://support.1password.com/1password-security/"],["1Password Business pricing","https://1password.com/pricing/business"]]},{"id":"bitwarden","name":"Bitwarden","job":"Password manager","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Partial","o":true,"loc":"EU","locs":["EU"],"hq":"US","co":"Bitwarden, Inc.","par":null,"parc":null,"store":"You pick US or EU in the server drop-down when you create the account or organisation. EU data sits in Microsoft Azure in the EU.","res":"yes-on-request","plans":"All cloud plans; choose the EU server at sign-up","mfa":"all plans","ai":"not-applicable","aid":"Vault data is encrypted on the device before it reaches Bitwarden's servers, so it cannot be read for training. No AI training use is described.","np":null,"note":"Choose the EU server when you sign up, because moving from US to EU later means exporting and re-importing everything. Most of the code is open source under GPL and AGPL, with some business features under Bitwarden's own licence.","conf":"high","src":[["Server Regions - Bitwarden","https://bitwarden.com/help/server-geographies/"],["Data Storage - Bitwarden","https://bitwarden.com/help/data-storage/"],["Export Vault Data - Bitwarden","https://bitwarden.com/help/export-your-data/"],["Two-step Login Methods - Bitwarden","https://bitwarden.com/help/setup-two-step-login/"],["bitwarden/server LICENSE","https://github.com/bitwarden/server/blob/main/LICENSE.txt"],["Bitwarden Privacy Policy","https://bitwarden.com/privacy/"]]},{"id":"lastpass","name":"LastPass","job":"Password manager","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"LastPass US LP","par":"Francisco Partners and Elliott Investment Management (private equity owners)","parc":"US","store":"US by default. LastPass also runs vault storage in Europe (Ireland, Germany, UK), used when elected at account creation.","res":"yes-on-request","plans":"Not stated by plan; region is elected when the account is created","mfa":"all plans","ai":"not-applicable","aid":"Vault contents are encrypted on the device and LastPass says it cannot read them. The privacy policy does not mention AI training for account or usage data.","np":null,"note":"Vaults are stored in the US unless Europe was chosen when the account was set up, so ask LastPass which region yours uses. LastPass had a major breach in 2022 that led to a UK ICO fine in 2025.","conf":"medium","src":[["LastPass Sub-Processors (April 2025)","https://www.lastpass.com/-/media/50dd502f16c34e99ad3ba7ea031d55ab.pdf"],["LastPass Technical and Organizational Measures (January 2025)","https://www.lastpass.com/-/media/175854c49fcb489baeaa87e78579e28f.pdf"],["LastPass Privacy Policy","https://www.lastpass.com/legal-center/privacy-policy"],["LastPass Pricing","https://www.lastpass.com/pricing"],["Import from LastPass - Bitwarden Help","https://bitwarden.com/help/import-from-lastpass/"],["LastPass - Wikipedia","https://en.wikipedia.org/wiki/LastPass"]]},{"id":"proton-pass","name":"Proton Pass","job":"Password manager","k":"Software","w":"Don't know","b":"UK or Europe","x":"Yes","o":false,"loc":"","locs":["CH","DE","NO"],"hq":"CH","co":"Proton AG","par":"Proton Foundation","parc":"CH","store":"Proton-owned servers located only in Switzerland, Germany or Norway. Proton does not say which country a given account uses and there is no customer choice.","res":"unclear","plans":null,"mfa":"all plans","ai":"not-applicable","aid":"Proton Pass data, including metadata, is end-to-end encrypted and Proton says it cannot decrypt it.","np":"Discounted rates for nonprofits on Proton Pass and other Proton services; rate not published.","note":"Your vault may be stored in Switzerland or Norway rather than the EU, although Switzerland and Norway have strong data protection laws. Business plans let admins require two-factor sign-in for everyone.","conf":"medium","src":[["Proton Pass Privacy Policy","https://proton.me/pass/privacy-policy"],["How to enforce 2FA for users","https://proton.me/support/pass-business-enforce-2fa"],["How to export passwords from Proton Pass","https://proton.me/support/pass-export"],["Password manager for nonprofits - Proton Pass","https://proton.me/business/pass/password-manager-for-nonprofits"],["Proton Pass security","https://proton.me/pass/security"],["Proton non-profit foundation","https://proton.me/blog/proton-non-profit-foundation"]]},{"id":"keepassxc","name":"KeePassXC","job":"Password manager","k":"App on our computers","w":"Don't know","b":"UK or Europe","x":"Yes","o":true,"loc":"","locs":[],"hq":"DE","co":"KeePassXC Team (volunteer open-source project)","par":null,"parc":null,"store":"On the user's own device, in an encrypted .kdbx file. It only goes elsewhere if you put the file in a cloud folder you choose.","res":"unclear","plans":null,"mfa":"unclear","ai":"not-applicable","aid":"The app runs locally and the project says no stored data is ever sent to it or third parties.","np":"Free for everyone.","note":"KeePassXC keeps passwords in a file on your own computer, so data location is wherever you save or sync that file. Decide where it is stored and backed up, and who holds the master password. It has no two-step sign-in in the usual sense: it uses a master password, with an optional key file or hardware key. Answer Yes to two-step sign-in only if you use one of those.","conf":"high","src":[["KeePassXC Password Manager","https://keepassxc.org/"],["KeePassXC User Guide","https://keepassxc.org/docs/KeePassXC_UserGuide"],["KeePassXC Privacy Policy","https://keepassxc.org/privacy/"],["KeePassXC Team","https://keepassxc.org/team"]]},{"id":"trello","name":"Trello","job":"Task boards","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"OTHER","co":"Atlassian (Trello)","par":"Atlassian Corporation","parc":"US","store":"US (AWS data centres). Trello is not listed among Atlassian products that offer data residency.","res":"no","plans":null,"mfa":"all plans","ai":"no","aid":"Atlassian's data contribution scheme, in force from 17 August 2026, uses metadata and in-app data from Free and Standard plans of Jira, Confluence and JSM for AI by default. Atlassian says it does not apply to Trello because Trello has no data contribution settings. Recheck if Trello gets these settings.","np":"Atlassian Social Impact licence: 75% off Trello Standard, Premium and Enterprise for eligible nonprofits.","note":"Trello data is held in the US and there is no option to move it to the UK or EU. Export each board to JSON from time to time, as spreadsheet and full workspace exports need Premium.","conf":"medium","src":[["Trello and GDPR - Our Commitment to Data Privacy","https://support.atlassian.com/trello/docs/trello-and-gdpr-our-commitment-to-data-privacy/"],["Understand data residency - Atlassian Support","https://support.atlassian.com/security-and-access-policies/docs/understand-data-residency/"],["Export data from Trello","https://support.atlassian.com/trello/docs/exporting-data-from-trello/"],["Data Contributions Frequently Asked Questions","https://www.atlassian.com/trust/ai/data-contribution/faqs"],["Data practices built for responsible AI","https://www.atlassian.com/trust/ai/data-contribution"],["Nonprofit Discount Eligibility and Pricing","https://www.atlassian.com/teams/nonprofits/discount-pricing"],["Enable two-factor authentication for your Trello account","https://support.atlassian.com/trello/docs/enabling-two-factor-authentication-for-your-trello-account/"]]},{"id":"asana","name":"Asana","job":"Project management","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Asana, Inc.","par":null,"parc":null,"store":"US (Virginia) by default. Frankfurt storage is a paid add-on on Enterprise and included in Enterprise+.","res":"yes-some-plans","plans":"Enterprise (paid add-on) and Enterprise+; region Frankfurt, Germany; no UK region","mfa":"all plans","ai":"no","aid":"Asana states it does not use customer data for training and its AI partners are contractually barred from doing so. Admins can switch AI features off in the admin console.","np":"Asana for Nonprofits: 50% off Starter and Advanced plans for eligible registered nonprofits, including outside the US.","note":"Asana keeps your data in the US unless you pay for Enterprise with the EU add-on. Only Enterprise plans can force everyone to use two-factor sign-in, so ask staff to turn it on themselves.","conf":"high","src":[["Asana data residency: where your data lives","https://help.asana.com/s/article/data-residency-for-asana?language=en_US"],["Asana Privacy Statement","https://asana.com/terms/privacy-statement"],["Asana AI FAQ","https://help.asana.com/s/article/asana-ai-faq?language=en_US"],["How to import & export projects in Asana","https://help.asana.com/s/article/project-importing-and-exporting?language=en_US"],["Mandatory two-factor authentication in Asana","https://help.asana.com/s/article/mandatory-two-factor-authentication?language=en_US"],["Asana for Nonprofits Discount Program","https://asana.com/industry/nonprofit"]]},{"id":"notion","name":"Notion","job":"Wiki and notes","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Yes","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Notion Labs, Inc.","par":null,"parc":null,"store":"US by default. Enterprise customers can choose Frankfurt (EU) for workspace content at no extra cost.","res":"yes-some-plans","plans":"Enterprise only; EU region Frankfurt; no UK region; Notion Mail and Calendar excluded","mfa":"all plans","ai":"no","aid":"Notion says it does not use workspace data to train models by default. Sharing is only through the opt-in AI LEAP programme. AI subprocessors are contractually barred from training on customer data.","np":"50% off the Business plan for eligible nonprofits worldwide (up to three workspaces), after verification.","note":"On non-Enterprise plans your Notion content is stored in the US. Two-step sign-in is available to everyone but admins cannot enforce it for members, so ask each person to switch it on.","conf":"high","src":[["Data residency for Notion","https://www.notion.com/help/data-residency"],["Export your content - Notion Help","https://www.notion.com/help/export-your-content"],["Notion's commitment to AI safety","https://www.notion.com/help/ai-safety"],["Two-step verification in Notion","https://www.notion.com/help/two-step-verification"],["Notion for nonprofits","https://www.notion.com/nonprofits"],["Notion (productivity software) - Wikipedia","https://en.wikipedia.org/wiki/Notion_(productivity_software)"]]},{"id":"airtable","name":"Airtable","job":"Shared databases","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Formagrid Inc (Airtable)","par":null,"parc":null,"store":"US by default. EU storage is only available on Enterprise Scale, and some metadata and login data stay in the US even then.","res":"yes-some-plans","plans":"Enterprise Scale only; EU region; no UK region","mfa":"all plans","ai":"no","aid":"Airtable's AI Terms say it will not use or let AI providers use customer data to train generative AI models. On Free, Team and similar plans, providers may keep inputs for up to 30 days for safety checks.","np":"50% off the Team plan for eligible registered nonprofits, including outside the US; monthly billing only; not for Business or Enterprise Scale.","note":"Airtable stores your bases in the US on the Team plan. Leaving is hard because export is one table at a time as CSV, so keep regular copies and save attachments separately.","conf":"high","src":[["Data residency at Airtable","https://support.airtable.com/docs/data-residency-at-airtable"],["Airtable Privacy Policy","https://www.airtable.com/company/privacy"],["Airtable AI Terms","https://www.airtable.com/company/ai-terms"],["Creating and managing Airtable bases","https://support.airtable.com/articles/7403739720-creating-and-managing-airtable-bases"],["Airtable export: CSV, Excel, backups and base limits","https://www.breeze.pm/articles/export-from-airtable"],["Airtable Trust & Security","https://www.airtable.com/company/trust-and-security"],["Applying for non-profit, education, and student Airtable plans","https://support.airtable.com/docs/nonprofit-and-educational-plans-faqs"]]},{"id":"monday-com","name":"monday.com","job":"Work management","k":"Software","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"","locs":["DE"],"hq":"OTHER","co":"monday.com Ltd.","par":null,"parc":null,"store":"Set by where the first user is when the account opens. Accounts opened from the EU on Standard, Pro or Enterprise go to the EU region (Germany); the UK is not named, and most others default to the US.","res":"yes-some-plans","plans":"Standard and Pro accounts created on or after 23 January 2023, and Enterprise; not Free or Basic","mfa":"all plans","ai":"no","aid":"monday.com says it does not use customer data to train AI models and bars its AI providers from doing so. It may access data temporarily, up to 60 days, to improve services and detect abuse; an admin can opt out by emailing ai-support@monday.com.","np":"10 free seats on the Pro plan for eligible nonprofits, 70% off extra seats and Pro add-ons, 33% off Enterprise; UK Community Interest Companies are excluded.","note":"Check Administration, then Profile, to see which region your account is stored in, because it is fixed when the account is created and cannot be moved later. UK charities should not assume EU storage.","conf":"medium","src":[["Data residency: where your data is stored","https://support.monday.com/hc/en-us/articles/4404392703250-Data-residency"],["monday.com Trust Center - Privacy","https://monday.com/trustcenter/privacy/overview"],["How to export your entire account's data","https://support.monday.com/hc/en-us/articles/360002543719-How-to-export-your-entire-account-s-data"],["Two-Factor Authentication","https://support.monday.com/hc/en-us/articles/360000787745-Two-Factor-Authentication"],["AI FAQs","https://support.monday.com/hc/en-us/articles/23227256685842-AI-FAQs"],["monday.com for nonprofits","https://support.monday.com/hc/en-us/articles/115005321269-monday-com-for-nonprofits"]]},{"id":"openproject-cloud","name":"OpenProject (cloud)","job":"Project management","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":true,"loc":"EU","locs":["EU"],"hq":"DE","co":"OpenProject GmbH","par":null,"parc":null,"store":"EU. The standard cloud runs on Amazon Web Services with all services in Europe; hosting on EU-owned Scaleway is available on request.","res":"yes-default","plans":"All cloud plans","mfa":"all plans","ai":"not-applicable","aid":"OpenProject does not run its own AI model. AI use is through its MCP server with a client and model the organisation chooses. Its privacy pages do not mention AI training.","np":"Special rates for NGOs and educational institutions on request from sales; no published discount.","note":"Your data stays in the EU, but on a US-owned cloud provider unless you ask for EU-owned Scaleway hosting. Check backup size, as attachments over 1 GB are left out of self-service backups.","conf":"medium","src":[["GDPR - OpenProject Enterprise cloud guide","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/gdpr-compliance/"],["Security and privacy - OpenProject","https://www.openproject.org/security-and-privacy/"],["OpenProject pricing","https://www.openproject.org/pricing/"],["Backups - OpenProject Enterprise cloud guide","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/backups/"],["Enterprise cloud FAQ","https://www.openproject.org/docs/enterprise-guide/enterprise-cloud-guide/enterprise-cloud-faq/"],["Two-factor authentication (2FA) - OpenProject","https://www.openproject.org/docs/system-admin-guide/authentication/two-factor-authentication/"],["OpenProject AI","https://www.openproject.org/ai/"]]},{"id":"zapier","name":"Zapier","job":"Connecting tools and moving data between them","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Zapier, Inc.","par":null,"parc":null,"store":"US. Zapier says it is hosted on Amazon Web Services in the United States, and that it does not offer EU-only storage. Zapier also passes your data between the other tools you connect, and each of those tools keeps its own copy.","res":"no","plans":"Plan assumed: Free, Professional or Team. Company and Enterprise differ on AI training.","mfa":"all plans","ai":"yes","aid":"Zapier's terms say it 'may derive de-identified data sets from your Customer Content' and use them 'to operate, enhance, improve, and develop Zapier products or services, including through model training'. Company and Enterprise plans are opted out automatically; on other plans you opt out with a form. Zapier's security page says it does not train on the data that runs through your workflows, on any plan. Checked 8 October 2026.","np":"15% off any paid plan (not pay-per-task charges) for non-profits, after Zapier checks proof of your non-profit status from your own country.","note":"Zapier moves data between your other tools, such as forms, email lists and accounts, and passes it through US servers on the way. List which tools each Zap touches, and check the settings of each one. Unless you are on Company or Enterprise, fill in Zapier's opt-out form if you do not want de-identified data from your content used for model training. You can export your Zaps and account data, but exporting Zaps is only for Team and Enterprise plans.","conf":"medium","src":[["Zapier security and compliance","https://zapier.com/security-compliance"],["Zapier pricing","https://zapier.com/pricing"],["Zapier for non-profits","https://zapier.com/non-profits"],["Discounts for Zapier plans","https://help.zapier.com/hc/en-us/articles/8496197165581-Discounts-for-Zapier-plans"],["Export or delete your Zapier account data","https://help.zapier.com/hc/en-us/articles/8496289406349-Export-or-delete-your-Zapier-account-data"],["Import and export Zaps in your Team or Enterprise account","https://help.zapier.com/hc/en-us/articles/8496308481933-Import-and-export-Zaps-in-your-Team-or-Enterprise-account"],["Zapier Terms of Service","https://zapier.com/legal/terms-of-service"],["Zapier data privacy","https://zapier.com/legal/data-privacy"]]}]},{"g":"Design","items":[{"id":"canva","name":"Canva","job":"Graphic design","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"OTHER","co":"Canva Pty Ltd","par":null,"parc":null,"store":"US by default. EU storage for designs and media is only offered on Enterprise, Campus and District plans.","res":"yes-some-plans","plans":"Enterprise (and Campus, District education plans); no UK option","mfa":"all plans","ai":"no","aid":"Canva says it does not use content to improve AI unless privacy settings allow it, and the default is off. Individual users can opt in or out in Privacy settings. Teams, Business and Enterprise accounts currently cannot opt in. Canva for Nonprofits runs as a team account.","np":"Canva for Nonprofits: free Canva Pro and team features for up to 50 people for eligible registered charities; extra seats at 50% off Enterprise pricing.","note":"Your designs are stored in the US on the Nonprofits plan, and EU storage is only available on Enterprise. Download important designs as PDF or PPTX regularly, because there is no editable export.","conf":"high","src":[["Set your organization's data residency preference - Canva Help Center","https://www.canva.com/help/data-residency/"],["Canva Trust Center - Privacy","https://www.canva.com/trust/privacy/"],["Canva Privacy Policy","https://www.canva.com/policies/privacy-policy/"],["Statement of Technical and Organisational Measures","https://www.canva.com/policies/technical-and-organisational-measures/"],["Canva for Nonprofits","https://www.canva.com/canva-for-nonprofits/"],["Choose the right download file type for your Canva design","https://www.canva.com/help/download-file-types/"],["Downloading your personal data, uploads, and designs in bulk","https://www.canva.com/help/bulk-download-data-uploads-designs/"],["Canva Help Center - login verification","https://www.canva.com/help/login-verification/"]]},{"id":"adobe-creative-cloud","name":"Adobe Creative Cloud","job":"Design, photo and print (Photoshop, Illustrator, InDesign)","k":"Software","w":"UK, EU or EEA","b":"Elsewhere","x":"Yes","o":false,"loc":"IE","locs":["IE"],"hq":"US","co":"Adobe Systems Software Ireland Limited","par":"Adobe Inc.","parc":"US","store":"Plan assumed: Creative Cloud for teams. Adobe cloud storage data centres are in Dublin (Ireland) for EMEA, Virginia (US) for North America and Tokyo for Japan, and your geographic region determines where files are stored. The UK is not named. Adobe's privacy policy says its main processing locations for personal information are the US and India.","res":"yes-default","plans":"Creative Cloud for teams (business storage, 1 TB per user, shared across the team). Your geographic region determines where files are stored; it is not chosen by you. Whether a UK organisation is placed in the EU region: unknown. Teams pricing: unknown.","mfa":"all plans","ai":"unclear","aid":"Adobe says it does not train Firefly on subscribers' personal content: 'No, Adobe does not train Adobe Firefly models or partner models on any Creative Cloud subscribers' personal content.' Separately, Adobe's content analysis setting lets Adobe analyse content stored on its servers to improve products; individuals can turn it off in their privacy settings. What applies to teams accounts is unknown, and an Adobe community thread reports there is no admin switch to turn it off for a whole team. Plan assumed: Creative Cloud for teams.","np":"Adobe for Non-profits (UK page): the offers are individual licences. Creative Cloud individual one-year memberships are discounted and run through TechSoup. For team-based access Adobe points non-profits to discounted Education Teams plans under its VIP buying programme. Teams prices: unknown.","note":"Export: you can download files from Adobe cloud storage on the web and export a whole Libraries collection, or single assets, from the Creative Cloud desktop app; colours, fonts and templates in a library cannot be exported. Cloud documents use Adobe's own formats (PSDC, AIC), so save a copy in a standard format from the app. When a teams licence is cancelled, storage for that licence drops to 5 GB and Adobe says you have 30 days to move anything above that out, after which some or all files may be removed. Check with your Adobe admin whether the content analysis setting is on for your team, and ask Adobe in writing which region your team's files are stored in, because the UK is not named. Photoshop, Illustrator and InDesign files also live on each person's computer unless saved to the cloud, so check where your team saves them. Nonprofit offers are individual licences through TechSoup; for a team, ask Adobe or a reseller about the discounted Education Teams plans under its VIP buying programme. Adobe offers a data processing addendum for business customers: ask for it. Teams pricing: unknown.","conf":"medium","src":[["Adobe cloud storage data centres - Adobe Help Center","https://helpx.adobe.com/uk/acrobat/web/manage-cloud-storage/manage-adobe-cloud-files/cloud-storage-data-centers.html"],["Content analysis FAQ for Creative Cloud and Document Cloud - Adobe Help Center","https://helpx.adobe.com/account/individual/terms-policies-and-regulations/content-analysis-faq.html"],["Adobe Firefly FAQ - Adobe Help Center","https://helpx.adobe.com/firefly/web/get-started/learn-the-basics/adobe-firefly-faq.html"],["Adobe Privacy Policy","https://www.adobe.com/privacy/policy.html"],["Adobe for Non-profits (UK)","https://www.adobe.com/uk/nonprofits/"],["Adobe for Nonprofits - TechSoup","https://www.techsoup.org/adobe-details"],["Secure user authentication and passwords - Adobe Help Center","https://helpx.adobe.com/enterprise/using/authentication-settings.html"],["Cancel Creative Cloud for teams licenses - Adobe Help Center","https://helpx.adobe.com/enterprise/using/cancel-teams-subscription.html"],["Export Creative Cloud libraries - Adobe Help Center","https://helpx.adobe.com/creative-cloud/apps/create-and-manage-libraries/manage-libraries/export-libraries.html"],["Cloud documents FAQ - Adobe Help Center","https://helpx.adobe.com/creative-cloud/help/cloud-document-faqs.html"],["Adobe Data Processing Addendum (June 2024)","https://www.adobe.com/cc-shared/assets/pdf/legal/terms/enterprise/pdfs/dpa-ww.pdf"]]},{"id":"figma","name":"Figma","job":"Design and prototyping","k":"Software","w":"Elsewhere","b":"Elsewhere","x":"Partial","o":false,"loc":"US","locs":["US"],"hq":"US","co":"Figma, Inc.","par":null,"parc":null,"store":"US by default. Figma's privacy policy says 'All personal information we process is transferred to, processed and stored in the United States, where our headquarters and our main servers are located.' Local file hosting (EU and other regions) is only on the Enterprise plan. Billing information, metadata, logs and file search data stay outside that option.","res":"yes-some-plans","plans":"Enterprise only (localised file hosting, EU among the regions). Plan assumed for the rest: Professional. No UK region listed.","mfa":"all plans","ai":"depends-on-plan","aid":"Figma's help centre says content training is on by default for Starter and Professional teams, and off for Organisation and Enterprise plans: 'By default, content training is turned on for Professional teams.' Team admins can turn it off on Starter and Professional. On Organisation and Enterprise it is currently disabled and cannot be switched on. Plan assumed: Professional.","np":"Figma says it has no nonprofit discount: 'We do not have any discounts for non-profits. Anyone is welcome to use Figma's free plan.' Students and educators can get the Education plan free. Professional Full seat is listed at USD 16 a month (US dollars).","note":"On the Starter and Professional plans, content training is switched on by default, so a team admin should check the setting and switch it off if you do not want your files used. Files are stored in the US unless you are on Enterprise. Two-step verification is available on any plan but each person sets it up, and only Enterprise with Governance+ lets an admin require it. You can save a local .fig copy of each file, which works in Figma only.","conf":"medium","src":[["Manage AI settings and content training - Figma Help Center","https://help.figma.com/hc/en-us/articles/17725942479127-Manage-AI-settings-and-content-training-for-your-team-or-organization"],["Enable localized file hosting - Figma Help Center","https://help.figma.com/hc/en-us/articles/15643274574871-Enable-localized-file-hosting"],["Privacy Policy - Figma","https://www.figma.com/legal/privacy/"],["Pricing FAQs - Figma","https://www.figma.com/pricing-faq/"],["Pricing - Figma","https://www.figma.com/pricing/"],["Enable two-factor authentication (2FA) - Figma Help Center","https://help.figma.com/hc/en-us/articles/360039817634-Enable-two-factor-authentication-2FA"],["Export static designs from Figma - Figma Help Center","https://help.figma.com/hc/en-us/articles/360040028114-Export-static-designs-from-Figma"]]},{"id":"affinity","name":"Affinity (by Canva)","job":"Design, photo and page layout","k":"App on our computers","w":"Don't know","b":"Elsewhere","x":"Yes","o":false,"loc":"","locs":[],"hq":"OTHER","co":"Canva UK Operations Ltd for UK billing addresses; Canva Pty Ltd (Australia) for most other countries, including Ireland and Denmark","par":"Canva","parc":"OTHER","store":"Your design files are stored on your own device and the supplier says it cannot access them. A Canva account is needed to download and activate the app. Anything you upload or export to Canva sits in your Canva account, and Affinity does not say where that is held.","res":"unclear","plans":"Plan assumed: the free Affinity app with a free Canva account. AI tools need a paid Canva plan.","mfa":"unclear","ai":"depends-on-plan","aid":"The supplier says content in Affinity is not used to train AI features. The Canva AI tools inside Affinity need a paid Canva plan and an internet connection, and content you upload or export to Canva follows your Canva privacy settings.","np":"Free for individuals. Whether Canva for Nonprofits terms apply to Affinity: unknown.","note":"Affinity keeps files on your computer, but you need a Canva account to get and activate it. Check who in your organisation owns that Canva account, and turn on two-step sign-in for it in the Canva account settings. Export: Affinity's help lists PNG, JPEG, GIF, TIFF, PSD, PDF, SVG, EPS, EXR and HDR. Your working files use Affinity's own .af format, so export a copy in a standard format for anything you need to keep long term. If anyone uses the paid AI tools or exports to Canva, check the Canva privacy settings for that content.","conf":"medium","src":[["Affinity","https://www.affinity.studio/"],["Affinity and Canva integrations (content stored locally, AI training)","https://www.affinity.studio/canva-integrations"],["Accessing Affinity for free with a Canva account (Canva Help Center)","https://www.canva.com/help/free-affinity-access/"],["Canva Terms of Use (contracting entity)","https://www.canva.com/policies/terms-of-use/"],["Set up Multi-Factor Authentication (Canva Help Center)","https://www.canva.com/help/login-verification/"],["Export Settings - Affinity Help Center","https://www.affinity.studio/help/sharing-export-settings/"]]},{"id":"gimp","name":"GIMP","job":"Photo editing","k":"App on our computers","w":"Don't know","b":"Elsewhere","x":"Yes","o":true,"loc":"","locs":[],"hq":"","co":"GIMP team (community project). Donations are handled by the GNOME Foundation as fiscal agent.","par":null,"parc":null,"store":"On your own device, in the files you save. It only goes elsewhere if you save or share those files to a cloud folder or service you choose.","res":"unclear","plans":null,"mfa":"no","ai":"not-applicable","aid":"The app runs on your device and the project says it does not collect, transmit, share or use any personal data. It checks for new versions no more than once a week in some builds.","np":"Free for everyone.","note":"GIMP has no account and no sign-in, so there is no two-step sign-in to switch on. Your images live wherever you save them, so decide where they are stored and backed up. The project says it collects no personal data, apart from a weekly update check in some builds. The US location is the GNOME Foundation that handles GIMP's donations, not a place where your data is held. Export: GIMP saves in its own XCF format, which 'is the only format that can store everything about an image', and exports to a wide variety of formats through File, then Export As (including PNG, JPEG and TIFF; it opens Photoshop PSD files). Keep an XCF copy for editing and an export for sharing.","conf":"medium","src":[["GIMP privacy policy","https://www.gimp.org/about/privacy.html"],["About GIMP (GNU General Public License)","https://www.gimp.org/about/"],["Donate to GIMP (GNOME Foundation as fiscal agent)","https://www.gimp.org/donating/"],["GIMP documentation: Saving and exporting","https://docs.gimp.org/3.0/en/gimp-images-out.html"],["GIMP documentation: Export File","https://docs.gimp.org/2.10/en/gimp-export-dialog.html"]]},{"id":"inkscape","name":"Inkscape","job":"Vector graphics and logos","k":"App on our computers","w":"Don't know","b":"Elsewhere","x":"Yes","o":true,"loc":"","locs":[],"hq":"","co":"Inkscape project, a member project of Software Freedom Conservancy (US non-profit)","par":null,"parc":null,"store":"On your own device, in the files you save. It only goes elsewhere if you save or share those files to a cloud folder or service you choose.","res":"unclear","plans":null,"mfa":"no","ai":"not-applicable","aid":"The app runs on your device and the project's privacy policy says the software does not collect or transmit any personal information.","np":"Free for everyone.","note":"Inkscape has no account and no sign-in, so there is no two-step sign-in to switch on. Your logos and drawings live wherever you save them, so decide where they are stored and backed up. Inkscape saves in SVG, an open standard that many other programs can read, and exports to PNG, PDF, EPS and other formats, so you can take your files with you. The US location is the Software Freedom Conservancy, which is the project's legal home, not a place where your data is held.","conf":"medium","src":[["Inkscape privacy policy","https://inkscape.org/about/privacy/"],["Inkscape governance (Software Freedom Conservancy)","https://inkscape.org/about/governance/"],["Inkscape signs new fiscal sponsorship agreement with SFC","https://inkscape.org/news/2015/11/08/new-fsa-with-software-freedom-conservancy/"],["Inkscape FAQ (SVG as native format)","https://inkscape.org/learn/faq/"],["About SVG (Inkscape)","https://inkscape.org/develop/about-svg/"],["Save as vs export (Inkscape wiki)","https://wiki.inkscape.org/wiki/Save_as_vs_export"]]}]},{"g":"Staff, payroll and HR","items":[{"id":"brightpay","name":"BrightPay","job":"Payroll (UK and Ireland)","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"EU","locs":["IE","GB","EU"],"hq":"IE","co":"Bright SG Ltd (BrightPay UK, London)","par":"Bright Software Group","parc":"IE","store":"Bright says its data is 'hosted in European regions', 'in EU/Ireland or UK ISO 27001 certified datacentres', and lists Microsoft Azure, AWS, OVH and Google as hosts. Its support desk (Zendesk) and email delivery (Twilio SendGrid) are in the US.","res":"unclear","plans":"Plan assumed: BrightPay cloud. Bright says only the cloud version is offered for 2026/27, and BrightPay for Windows was discontinued after 5 April 2026. Price depends on the number of employers and employees, and Bright points to a pricing calculator; monthly or annual billing is offered. Fixed price: unknown.","mfa":"all plans","ai":"unclear","aid":"Unknown. Bright's subprocessor list names no AI provider.","np":null,"note":"BrightPay holds payroll and employee data, so ask Bright where your cloud data sits: it says Ireland, UK or EU, not one country. Two-factor sign-in is optional, and an owner or administrator can make it compulsory for every user. Bright's cloud FAQ says you cannot save a file of your payroll data to your computer, but reports can be downloaded as CSV or PDF, so save your reports after each pay run. If you still use desktop BrightPay, check your backup is on your own storage, as that version has ended.","conf":"medium","src":[["Security","https://brightsg.com/security/"],["Subprocessors","https://brightsg.com/subprocessors/"],["About Bright","https://brightsg.com/en-ie/about-bright/"],["Two Factor Authentication FAQs","https://www.brightpay.co.uk/docs/bpol/two-factor-authentication-users/two-factor-authentication-faqs/"],["GDPR and BrightPay FAQs","https://www.brightpay.co.uk/docs/24-25/gdpr/frequently-asked-questions/"],["Exporting reports","https://www.brightpay.co.uk/docs/23-24/analysis/exporting-reports/"],["BrightPay cloud payroll software","https://brightsg.com/brightpay-cloud-payroll-software/"],["BrightPay Terms and Conditions","https://payrollsupport.uk.brightsg.com/hc/en-gb/articles/40934791839249-BrightPay-Terms-and-Conditions"],["BrightPay cloud FAQ","https://brightsg.com/brightpay-cloud-faq/"]]},{"id":"sage-payroll","name":"Sage Payroll","job":"Payroll","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"IE","locs":["IE"],"hq":"GB","co":"Sage (UK) Ltd","par":null,"parc":null,"store":"Ireland. Sage's list of sub-processors names Amazon Web Services (a US company) for data hosting and cloud infrastructure for Sage Business Cloud Payroll, with hosting and processing in Ireland. Some other sub-processors process data in the USA, including Postmark, which sends payslip and pension letter emails. Plan: cloud Sage Payroll.","res":"unclear","plans":"Plan assumed: cloud Sage Payroll (Essentials, Standard or Premium). Sage 50 Payroll on your own computer is a different product and is not covered.","mfa":"all plans","ai":"unclear","aid":"Unknown for Sage Payroll specifically. Sage's general AI and data ethics page says it analyses product data together with data from other Sage customers to develop and train AI models, where the law allows. Ask Sage whether this applies to your payroll data and whether you can opt out.","np":null,"note":"Payroll holds names, addresses, National Insurance numbers, pay and bank details. You contract with Sage (UK) Ltd unless your invoices name another Sage company. Sage's help says cloud Sage Payroll cannot export all your payroll data at once or take a backup, so run and save your reports (the detailed pay run report can be saved as CSV) after each pay run. Sage does not delete your data for six months after the agreement ends, and may delete it after that. Two-factor authentication is mandatory for everyone who logs in, and each user needs their own login. Ask Sage in writing whether your payroll data is used to train AI.","conf":"low","src":[["Sage Payroll FAQs (Sage knowledge base)","https://gb-kb.sage.com/portal/app/portlets/results/viewsolution.jsp?solutionid=250916100556683"],["The detailed payroll report (Sage knowledge base)","https://gb-kb.sage.com/portal/app/portlets/results/view2.jsp?k2dockey=222001000101657"],["Export payroll data (Sage help)","https://gb-kb.sage.com/portal/app/portlets/results/viewsolution.jsp?solutionid=222001000101649"],["Sage Payroll (product page)","https://www.sage.com/en-gb/sage-business-cloud/payroll/"],["Customer due diligence: sub-processors (Sage)","https://www.sage.com/en-gb/trust-security/privacy/customer-due-diligence/"],["Data ethics and principles at Sage","https://www.sage.com/en-us/trust-security/ai-ethics/"],["Sage Cloud Services Terms of Service (August 2026)","https://www.sage.com/en-gb/-/media/files/sagedotcom/uk/documents/pdf/legal/sage%20cloud%20services%20terms%20of%20service%20august%202026.pdf"],["Set up 2-factor authentication (Sage help)","https://gb-kb.sage.com/portal/app/portlets/results/view2.jsp?k2dockey=230630113527747"]]},{"id":"brighthr","name":"BrightHR","job":"HR, absence and staff records","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Partial","o":false,"loc":"GB","locs":["GB"],"hq":"GB","co":"Bright HR Limited","par":null,"parc":null,"store":"UK for customers who subscribe in the UK. BrightHR says it stores data in the country of subscription, on Microsoft Azure. Irish subscribers' data is kept in the EU.","res":"yes-default","plans":"Plan assumed: any UK subscription (Core HR Software, Enhanced HR Support or Full HR, Health & Safety and Wellbeing). BrightHR does not tie the storage location to a plan.","mfa":"unclear","ai":"unclear","aid":"Unknown. BrightHR's security page says nothing about using customer data to train AI.","np":null,"note":"Staff records, absence and documents are kept in the UK when you subscribe in the UK. BrightHR says you can export data at any time through reports (Employees, Absence, Documents), downloaded as CSV or Excel, but it does not describe a single full export, so ask what you would receive on leaving. Two-factor sign-in is available: each user turns it on in My Account using an authenticator app. Which plans have it, and whether an administrator can require it for everyone, is unknown, so check your admin settings. Contracts run for 24, 36 or 60 months, so check the length and the notice terms before you sign.","conf":"medium","src":[["BrightHR security","https://www.brighthr.com/security/"],["BrightHR pricing","https://www.brighthr.com/pricing/"],["BrightHR help: how do you manage data and systems security","https://help.brighthr.com//faqs/gdpr-and-security/how-do-you-manage-data-and-systems-security/"],["BrightHR help: account security and two-factor authentication","https://help.brighthr.com//guides/everything-you-need-to-know-about-account-security/"],["BrightHR help: managing your HR and payroll data transfer","https://help.brighthr.com//guides/managing-your-hr-and-payroll-data-transfer/"]]},{"id":"breathe-hr","name":"Breathe HR","job":"HR, holiday and staff records","k":"Software","w":"UK, EU or EEA","b":"UK or Europe","x":"Yes","o":false,"loc":"GB","locs":["GB"],"hq":"GB","co":"Centurion Management Systems Ltd (trading as Breathe)","par":"ELMO Software","parc":"OTHER","store":"UK. Breathe says it uses the AWS London region (eu-west-2), with a failover centre elsewhere in the UK, and that none of your data leaves the UK.","res":"yes-default","plans":"All plans (Micro, Starter, Regular, Pro, Premium, Plus). Breathe does not state a plan condition on where data is kept.","mfa":"all plans","ai":"unclear","aid":"Unknown. Breathe says it holds ISO 42001 (AI management) certification and that aggregated usage data is redacted before it reaches its business intelligence system, but it does not state whether customer data is used to train AI models.","np":null,"note":"Staff records are kept in London on Amazon Web Services. Breathe says you can export employee data and download documents yourself. Its help says two-factor sign-in is on for Admin accounts, and from 25 August 2026 it is being switched on for HR accounts in batches, so check it is on for everyone who can see staff records. Breathe is owned by an Australian company, ELMO, so check which entity is named on your order.","conf":"medium","src":[["Security and reliability (Breathe)","https://www.breathehr.com/en-gb/hr-software/security-reliability/security-and-reliability"],["HR software security (Breathe)","https://www.breathehr.com/en-gb/hr-software/security-reliability"],["Managing two-factor authentication (Breathe help)","https://intercom.help/breathehr/en/articles/4829187-managing-two-factor-authentication-2fa"],["HR software prices (Breathe)","https://www.breathehr.com/en-gb/hr-software/hr-software-prices"]]}]},{"g":"Social media and advertising","items":[{"id":"google-ads","name":"Google Ads (including Google Ad Grants)","job":"Search and online advertising","k":"Software","w":"Don't know","b":"Elsewhere","x":"Yes","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"Google Ireland Limited, or Google Commerce Limited where the account's purpose of use is 'eligible non-business use'","par":null,"parc":null,"store":"Unknown. Google's data processing terms say it \"may process Customer Personal Data in any country in which Google or its Subprocessors maintain facilities\". Google lists its data centre locations publicly.","res":"unclear","plans":"Plan assumed: a standard Google Ads account, and the Google Ad Grants account for eligible charities. Google does not say the data location differs.","mfa":"unclear","ai":"unclear","aid":"Unknown.","np":"Google Ad Grants: up to USD 10,000 a month in search ads on Google.com for qualifying non-profits. Your organisation must hold valid charity status in your country and be verified through Google for Nonprofits first.","note":"Google Ads does not tell you one place your data is kept, so check the data processing terms for your account. You can download reports and account data as CSV and other files. Ad Grants is search ads only, and you apply through Google for Nonprofits first. Google \"strongly encourages all advertisers to use 2-Step Verification\". An account administrator can turn the requirement on or off under Access and security, so turn it on. On a UK account the contract is with Google Commerce Limited if you chose 'eligible non-business use' when you signed up, and otherwise with Google Ireland Limited.","conf":"low","src":[["Google Ad Grants","https://www.google.com/grants/"],["Google Ad Grants eligibility","https://www.google.com/grants/get-started/"],["Google Ads Data Processing Terms","https://business.safety.google/adsprocessorterms/"],["Google Ireland Limited Advertising Programme Terms (1 July 2026)","https://payments.google.com/payments/apis-secure/get_legal_document?ldi=352992"],["Secure your Google Ads account: 2-Step Verification","https://support.google.com/google-ads/answer/12864186"],["Export account data to a spreadsheet (CSV), Google Ads Editor Help","https://support.google.com/google-ads/editor/answer/38657"]]},{"id":"facebook-page","name":"Facebook Page","job":"Organisation page and Messenger inbox","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"Meta Platforms Ireland Limited (controller for people in the UK and EEA)","par":"Meta Platforms, Inc.","parc":"US","store":"Unknown. Plan assumed: a free Facebook Page. Meta's privacy policy says it shares information across its offices and data centres worldwide, and relies on the EU-US Data Privacy Framework for European data sent to Meta Platforms, Inc. in the US. Where a Page's posts or Messenger inbox are kept: unknown.","res":"unclear","plans":null,"mfa":"all plans","ai":"unclear","aid":"Meta says it uses public posts and comments from adult users' accounts on Facebook and Instagram to improve its generative AI models, and that it does not use private messages with friends and family unless someone in the chat shares them with its AI (UK announcement, 13 September 2024; EU announcement, 14 April 2025). UK and EU users can send an objection form. Whether a Page's public posts count: unknown.","np":null,"note":"Facebook Pages are run through people's own Facebook logins, so check who holds full control. Aim for at least two trusted people, each with two-step login switched on and recovery details they can still reach. Meta says a Page with nobody holding full control is deactivated and scheduled for deletion. Messenger messages from supporters sit in the Page inbox. Meta says a person with full control can download a copy of the Page and choose which categories of information to include. Insights can be exported from Meta Business Suite. Whether the Messenger inbox is included: unknown. Test a download before you rely on it.","conf":"medium","src":[["Meta Privacy Policy","https://www.facebook.com/privacy/policy/"],["Meta Data Processing Terms","https://www.facebook.com/legal/terms/dataprocessing"],["Download a copy of your Facebook Page","https://www.facebook.com/help/466076673571942"],["Export your Page's insights data","https://m.facebook.com/help/www/972879969525875"],["About Facebook Page access","https://www.facebook.com/help/289207354498410"],["Request Facebook access to a Page","https://www.facebook.com/help/531084028683914"],["How Meta uses information for generative AI models","https://www.facebook.com/privacy/genai/"],["Building AI technology for the UK (Meta, 13 September 2024)","https://about.fb.com/news/2024/09/building-ai-technology-for-the-uk-in-a-responsible-and-transparent-way/"],["Making AI work harder for Europeans (Meta, 14 April 2025)","https://about.fb.com/news/2025/04/making-ai-work-harder-for-europeans/"]]},{"id":"instagram-professional","name":"Instagram (professional account)","job":"Organisation account, posts and direct messages","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"Meta Platforms Ireland Limited (controller for people in the UK and EEA)","par":"Meta Platforms, Inc.","parc":"US","store":"Unknown. Plan assumed: a free professional (business or creator) account. Meta's privacy policy covers Instagram and says it shares information across its offices and data centres worldwide. Where an account's posts or direct messages are kept: unknown.","res":"unclear","plans":null,"mfa":"all plans","ai":"unclear","aid":"Meta says it uses public posts and comments from adult users' accounts on Facebook and Instagram to improve its generative AI models, and that it does not use private messages with friends and family unless someone in the chat shares them with its AI (UK announcement, 13 September 2024; EU announcement, 14 April 2025). UK and EU users can send an objection form. Whether a professional account counts: unknown.","np":null,"note":"An Instagram professional account is still tied to one login. Check who knows the password, which email address and phone number are on it for recovery, and whether two-step login is on. If you connect it to a Facebook Page or a Business Portfolio, check who holds admin access there, because switching the account back to personal disconnects the Page and removes access to ads tools. Instagram's Export your information tool lets you download a profile's data, and Instagram lists messages among the types of information you can choose. Test an export before you rely on it.","conf":"medium","src":[["Review and export a copy of your Instagram information","https://help.instagram.com/181231772500920"],["About professional accounts on Instagram","https://help.instagram.com/138925576505882"],["Switch back to a personal Instagram account","https://help.instagram.com/1717693135113805/"],["Securing your Meta Account with two-factor authentication","https://help.instagram.com/566810106808145"],["Add an Instagram account to your business portfolio","https://www.facebook.com/business/help/620548115562686"],["Meta Privacy Policy","https://www.facebook.com/privacy/policy/"],["Building AI technology for the UK (Meta, 13 September 2024)","https://about.fb.com/news/2024/09/building-ai-technology-for-the-uk-in-a-responsible-and-transparent-way/"],["Making AI work harder for Europeans (Meta, 14 April 2025)","https://about.fb.com/news/2025/04/making-ai-work-harder-for-europeans/"],["Information available to download from your Instagram profile","https://help.instagram.com/6947552812036899"]]},{"id":"linkedin-company-page","name":"LinkedIn Company Page","job":"Organisation page and followers","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"LinkedIn Ireland Unlimited Company (controller for people in the UK and EEA)","par":"Microsoft Corporation","parc":"US","store":"Unknown. Plan assumed: a free LinkedIn Page. LinkedIn's privacy policy says it processes data both inside and outside the United States and uses legal mechanisms for transfers. Where a Page's content is kept: unknown.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"LinkedIn says that from 3 November 2025 it can use some data from members in the UK, EU, EEA, Switzerland, Canada and Hong Kong to train AI models that create content. It names profile details and public content members post, and says it does not include private messages. For UK members the same setting also controls whether LinkedIn shares this data with Microsoft for Microsoft's model training. Members can turn this off in their own settings (Data for Generative AI Improvement), which is on by default. The setting belongs to each member's account, not to the Page.","np":null,"note":"A LinkedIn Page is managed by people's personal LinkedIn profiles. LinkedIn says every Page needs at least one super admin, so check that at least two trusted people hold that role, and that each has two-step verification on and can recover their own login. If the only admin leaves, other people have to request access and current super admins must approve it. LinkedIn says you can \"create and export reports for analytics on visitors, content, followers, and competitors\" as an XLS file. Export of follower lists and Page messages: unknown, so check what you can take out before you depend on it.","conf":"medium","src":[["Export your LinkedIn Page analytics report","https://www.linkedin.com/help/linkedin/answer/a551206/"],["LinkedIn Page admin roles","https://www.linkedin.com/help/linkedin/answer/a541981"],["Request admin access to a LinkedIn Page","https://www.linkedin.com/help/linkedin/answer/a569092"],["Two-step verification overview","https://www.linkedin.com/help/linkedin/answer/a1358878"],["Create a LinkedIn Page","https://www.linkedin.com/help/linkedin/answer/a543852"],["Update to our Terms and data use","https://www.linkedin.com/help/linkedin/answer/a8059228"],["LinkedIn Privacy Policy","https://www.linkedin.com/legal/privacy-policy"],["LinkedIn and generative AI (GAI) FAQs","https://www.linkedin.com/help/linkedin/answer/a5538339"],["Control whether LinkedIn uses your data to improve generative AI models","https://www.linkedin.com/help/linkedin/answer/a6278444"]]},{"id":"meta-business-suite","name":"Meta Business Suite (Business Portfolio)","job":"Admin layer over Facebook Pages, Instagram accounts and ads","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Partial","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"Meta Platforms Ireland Limited (controller for people in the UK and EEA)","par":"Meta Platforms, Inc.","parc":"US","store":"Unknown. Plan assumed: the free Meta Business Suite with a Business Portfolio. Meta's Data Processing Terms, which cover its business tools, say Meta may use sub-processors based in the USA, the EU or EEA, or other countries, and do not name where data is processed.","res":"unclear","plans":null,"mfa":"all plans","ai":"unclear","aid":"Unknown. Meta's generative AI statements (UK, 13 September 2024; EU, 14 April 2025) are about public posts from adult users' Facebook and Instagram accounts. Whether they apply to Business Portfolio or Business Suite data: unknown.","np":null,"note":"A Business Portfolio is only as safe as the personal Facebook logins behind it. Check who has full control, and that at least two trusted people do. Meta says two-factor authentication is required for some portfolios more than 90 days old, and that only people with full control can require it for everyone. Check your Pages and Instagram account are added to the portfolio, not only to one person's profile. Deleting a portfolio moves its Pages back to a personal profile. Insights can be exported (CSV, PDF or PNG). The portfolio's settings and people list have no export, so note them down.","conf":"medium","src":[["About Business Portfolios","https://www.facebook.com/business/help/486932075688253"],["How Meta Business Suite Works","https://www.facebook.com/business/help/205614130852988"],["Turn on the two-factor authentication requirement in your business portfolio","https://www.facebook.com/business/help/280940009201586"],["Remove people from your business portfolio","https://www.facebook.com/business/help/353397428740939"],["Delete your business portfolio","https://www.facebook.com/business/help/1592865014304024"],["Request access to a Page in Meta Business Suite","https://www.facebook.com/business/help/183277585892925"],["What can I do if I've lost access to my account?","https://www.facebook.com/business/help/793704920815911"],["Meta Data Processing Terms","https://www.facebook.com/legal/terms/dataprocessing"],["Building AI technology for the UK (Meta, 13 September 2024)","https://about.fb.com/news/2024/09/building-ai-technology-for-the-uk-in-a-responsible-and-transparent-way/"]]},{"id":"x-twitter","name":"X (formerly Twitter)","job":"Organisation account, posts and direct messages","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Yes","o":false,"loc":"UNKNOWN","locs":[],"hq":"US","co":"X Internet Unlimited Company, Ireland (named Twitter International Unlimited Company in earlier terms; controller for people in the UK, EU and EFTA states). Parent company: unknown.","par":"","parc":"","store":"Plan assumed: a free X account. Where an account's posts and messages are kept: unknown. X's global operations help page says information may be transferred to and stored in the United States, Ireland and other countries, and that X uses Standard Contractual Clauses where they apply.","res":"unclear","plans":null,"mfa":"all plans","ai":"yes","aid":"X's privacy policy says X may share public posts and how you interact with Grok with xAI. X's Grok help page describes a setting under Privacy and safety, Data sharing and personalization, Grok & Third-party Collaborators, to allow or stop your public data and Grok interactions being used for training and fine-tuning. The setting is per account and does not remove data already collected. Privacy policy dated 15 July 2026. Updated Terms of Service take effect 9 October 2026, so check them again after that date.","np":null,"note":"X's terms say the contract for people in the UK, EU and EFTA states is with an Irish company. Parent company: unknown. Check who holds the login: X has a Delegate feature that lets people act for an account with an Admin or Contributor role, without sharing the password. Set it up so at least two trusted people can get in, then turn on two-step login for the main account. Authenticator app and security key are open to everyone; text message codes are for Premium subscribers only, so check which method you are using. You can download an archive of your data (profile, posts, direct messages, media, followers and lists, in HTML and JSON files) from Settings; ask for it before you need it. Check the Grok data-sharing setting on the account, and read the new terms before they start on 9 October 2026. Confirm the Delegate rules and the setting names in the account itself.","conf":"medium","src":[["X Privacy Policy","https://x.com/en/privacy"],["X Privacy Policy, 15 July 2026 (PDF)","https://legal.x.com/content/dam/legal-twitter/site-assets/x-privacy-policy-2026-07-15/en/x-privacy-policy-2026-07-15.pdf"],["X Terms of Service","https://x.com/en/tos"],["X Terms of Service, 10 April 2026 (PDF)","https://legal.x.com/content/dam/legal-twitter/site-assets/x-terms-of-service-2026-04-10/en/x-terms-of-service-2026-04-10.pdf"],["Our global operations and data transfer","https://help.x.com/en/rules-and-policies/global-operations-and-data-transfer"],["About Grok (X Help Center)","https://help.x.com/en/using-x/about-grok"],["How to use two-factor authentication","https://help.x.com/en/managing-your-account/two-factor-authentication"],["How to access and download your X data","https://help.x.com/en/managing-your-account/accessing-your-x-data"],["How to use the Delegate feature","https://help.x.com/en/managing-your-account/how-to-use-the-delegate-feature"],["How to download your X archive","https://help.x.com/en/managing-your-account/how-to-download-your-x-archive"]]},{"id":"bluesky","name":"Bluesky","job":"Organisation account and posts","k":"Account on a platform","w":"Don't know","b":"Elsewhere","x":"Partial","o":true,"loc":"UNKNOWN","locs":[],"hq":"US","co":"Bluesky Social, PBC (controller; representatives named for the UK and EEA). Parent company: unknown.","par":"","parc":"","store":"Plan assumed: a free Bluesky account on the Bluesky-run server. Country where an account is kept: unknown. Bluesky's privacy policy says: \"We may transfer, process, and store all personal information we collect anywhere in the world.\" It relies on Standard Contractual Clauses for transfers out of the EEA, UK and Switzerland.","res":"unclear","plans":null,"mfa":"all plans","ai":"no","aid":"Bluesky's privacy policy and terms (both last updated 14 August 2025) say nothing on training AI with your content. On its own account Bluesky said on 15 November 2024: 'We do not use any of your content to train generative AI, and have no intention of doing so.' It said later that month: 'Bluesky will not train generative AI on user data.' These are public statements, not terms of the contract. Posts, likes, follows and blocks are public by design on the network, so other people and companies can collect them.","np":null,"note":"Bluesky is built on the AT Protocol, which is open source (MIT and Apache 2.0). Anyone can run their own server for an account (a PDS), and an account can move from one server to another, so exit is possible. The move needs care: it needs proof of control of the account, big accounts can hit errors and upload limits, and the guide is written for technical people. You can export your public records from Settings as a CAR file. The file does not hold images or private data; images are downloaded separately through the API, one by one. Two-step login by email code is available. App passwords let a scheduling tool sign in without your main password. Check who holds the password: no team or shared-access feature is documented, so at least two trusted people may need to know the login, kept in a shared password manager. Organisations can apply for a verification badge through Bluesky's form; ask if it is right for you. The promise not to train AI is a public post, not a term of the contract, and your posts are public, so check the AI position yourself.","conf":"medium","src":[["Bluesky Privacy Policy (14 August 2025)","https://bsky.social/about/support/privacy-policy"],["Bluesky Terms of Service (14 August 2025)","https://bsky.social/about/support/tos"],["Bluesky AT Protocol Network Services Privacy Notice","https://bsky.social/about/support/network-services-privacy-policy"],["Bluesky post on generative AI, 15 November 2024","https://bsky.app/profile/bsky.app/post/3layuzbto2c2x"],["AT Protocol account migration","https://atproto.com/guides/account-migration"],["AT Protocol self-hosting","https://atproto.com/guides/self-hosting"],["AT Protocol reference implementation (licence)","https://github.com/bluesky-social/atproto"],["Download and parse repository exports","https://atproto.com/blog/repo-export"],["A new form of verification on Bluesky","https://bsky.social/about/blog/04-21-2025-verification"],["Bluesky post on generative AI, 26 November 2024","https://bsky.app/profile/bsky.app/post/3lbvgvbviak2c"],["Bluesky app export dialog (source code)","https://github.com/bluesky-social/social-app/blob/main/src/screens/Settings/components/ExportCarDialog.tsx"]]}]}];
